/* CYRUS landing v7: a black-and-white instrument language with electric blue + violet energy. */
@font-face{font-family:"Grotesk";src:url(../fonts/sg-500.woff2) format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:"Grotesk";src:url(../fonts/sg-600.woff2) format("woff2");font-weight:600 700;font-display:swap}
@font-face{font-family:"Inter";src:url(../fonts/inter-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Inter";src:url(../fonts/inter-600.woff2) format("woff2");font-weight:500 700;font-display:swap}
@font-face{font-family:"Mono";src:url(../fonts/jb-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Mono";src:url(../fonts/jb-500.woff2) format("woff2");font-weight:500 700;font-display:swap}

:root{
  --bg:#000;--ink:#fff;--ink-2:rgba(255,255,255,.74);--ink-3:rgba(255,255,255,.56);--ink-4:rgba(255,255,255,.34);
  --line:rgba(255,255,255,.09);--line-2:rgba(255,255,255,.16);
  --blue:#3d7bff;--blue-hi:#79a6ff;--violet:#8b5cff;--violet-hi:#b49bff;
  --glass:rgba(255,255,255,.035);--glass-2:rgba(255,255,255,.06);
  --energy:linear-gradient(100deg,var(--blue),var(--violet));
  --r:18px;--r-sm:12px;--gut:clamp(16px,4vw,48px);--max:1240px;
  --display:"Grotesk","Inter",system-ui,sans-serif;--body:"Inter",system-ui,sans-serif;--mono:"Mono",ui-monospace,monospace;
  color-scheme:dark;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 var(--body);-webkit-font-smoothing:antialiased;overflow-x:hidden}
img,svg,canvas{display:block;max-width:100%}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}
a{color:inherit}
::selection{background:var(--violet);color:#fff}
:focus-visible{outline:2px solid var(--blue-hi);outline-offset:3px;border-radius:6px}
.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip{position:fixed;left:16px;top:-60px;z-index:100;background:#fff;color:#000;padding:10px 14px;border-radius:10px;font-weight:600;text-decoration:none}
.skip:focus{top:12px}
.wrap{width:100%;max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
.mono{font-family:var(--mono);letter-spacing:.02em}
.grad-text{background:var(--energy);-webkit-background-clip:text;background-clip:text;color:transparent}

/* ---------- nav ---------- */
.nav{position:fixed;inset:0 0 auto 0;z-index:50;transition:background .4s,border-color .4s,backdrop-filter .4s;border-bottom:1px solid transparent}
.nav.scrolled{background:rgba(0,0,0,.62);backdrop-filter:blur(16px) saturate(140%);-webkit-backdrop-filter:blur(16px) saturate(140%);border-color:var(--line)}
.nav .wrap{display:flex;align-items:center;gap:28px;height:68px}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none}
.brand img{height:22px;width:auto}
.nav-links{display:flex;gap:4px;margin-left:auto;list-style:none;padding:0;margin-top:0;margin-bottom:0}
.nav-links a{display:block;padding:8px 12px;border-radius:999px;color:var(--ink-3);text-decoration:none;font-size:14px;transition:color .2s,background .2s}
.nav-links a:hover{color:var(--ink);background:var(--glass-2)}
.nav-cta{display:flex;gap:8px;align-items:center}
.menu-btn{display:none;margin-left:auto;background:none;border:1px solid var(--line-2);border-radius:999px;width:40px;height:40px;place-items:center}
.menu-btn span{display:block;width:16px;height:1.5px;background:#fff;margin:3px auto;transition:transform .3s}
.menu-btn[aria-expanded=true] span:first-child{transform:translateY(2.25px) rotate(45deg)}
.menu-btn[aria-expanded=true] span:last-child{transform:translateY(-2.25px) rotate(-45deg)}

/* ---------- buttons ---------- */
.btn{--h:44px;position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;height:var(--h);padding:0 20px;border-radius:999px;border:1px solid var(--line-2);background:transparent;color:var(--ink);font-weight:600;font-size:15px;text-decoration:none;white-space:nowrap;transition:transform .25s cubic-bezier(.2,.8,.2,1),background .25s,border-color .25s,box-shadow .3s}
.btn:hover{border-color:rgba(255,255,255,.4);background:var(--glass-2)}
.btn:active{transform:scale(.97)}
.btn-sm{--h:38px;padding:0 16px;font-size:14px}
.btn-lg{--h:54px;padding:0 28px;font-size:16px}
.btn-solid{background:#fff;color:#000;border-color:#fff}
.btn-solid:hover{background:#fff;border-color:#fff;box-shadow:0 0 0 1px rgba(255,255,255,.6),0 10px 40px -8px rgba(61,123,255,.75),0 10px 60px -10px rgba(139,92,255,.7)}
.btn-solid .arrow{transition:transform .3s}
.btn-solid:hover .arrow{transform:translateX(3px)}
.btn-create{--h:52px;padding:0 24px;background:#fff;color:#000;border:0;overflow:hidden;isolation:isolate}
.btn-create::before{content:"";position:absolute;inset:-2px;z-index:-1;background:conic-gradient(from var(--a,0deg),var(--blue),var(--violet),#fff,var(--blue));opacity:0;transition:opacity .35s}
.btn-create::after{content:"";position:absolute;inset:2px;z-index:-1;border-radius:inherit;background:#fff}
.btn-create:hover::before,.btn-create.busy::before{opacity:1;animation:spin 2.4s linear infinite}
.btn-create:hover{box-shadow:0 12px 50px -10px rgba(61,123,255,.8),0 12px 60px -12px rgba(139,92,255,.8)}
@property --a{syntax:"<angle>";inherits:false;initial-value:0deg}
@keyframes spin{to{--a:360deg}}

/* ---------- hero ---------- */
.hero{position:relative;min-height:100vh;min-height:100svh;padding-top:68px;overflow:hidden;isolation:isolate}
.hero-bg{position:absolute;inset:0;z-index:-2;pointer-events:none}
.hero-bg::before{content:"";position:absolute;left:50%;top:34%;width:1100px;height:1100px;transform:translate(-50%,-50%);background:radial-gradient(closest-side,rgba(61,123,255,.16),rgba(139,92,255,.06) 55%,transparent 72%)}
.hero-bg::after{content:"";position:absolute;inset:0;background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:64px 64px;mask-image:radial-gradient(ellipse 60% 55% at 50% 38%,#000 0%,transparent 75%);-webkit-mask-image:radial-gradient(ellipse 60% 55% at 50% 38%,#000 0%,transparent 75%);opacity:.45}
#particles{position:absolute;inset:0;width:100%;height:100%;z-index:-1}
.stage{position:relative;height:clamp(420px,56vh,540px);max-width:1320px;margin:0 auto}
.core{position:absolute;left:50%;top:50%;width:var(--core);height:var(--core);transform:translate(-50%,-50%);--core:min(520px,46vh)}
.core canvas{position:absolute;inset:0;width:100%;height:100%;mix-blend-mode:screen}
.rings{position:absolute;inset:-30%;width:160%;height:160%;overflow:visible;pointer-events:none}
.rings.front{z-index:3}
.rings ellipse,.rings path{fill:none}
.core-label{position:absolute;left:50%;bottom:4%;transform:translateX(-50%);font:500 11px var(--mono);letter-spacing:.24em;color:var(--ink-4);text-transform:uppercase;white-space:nowrap;z-index:4;transition:color .3s}
.core-label b{color:var(--ink);font-weight:500}
#streams{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;z-index:1}
#streams .base{stroke:rgba(255,255,255,.07);stroke-width:1;fill:none}
#streams .flow{fill:none;stroke-width:1.4;stroke-dasharray:1.5 11;stroke-linecap:round;opacity:.35;animation:flow 1.8s linear infinite;transition:opacity .4s,stroke-width .4s}
#streams .flow.on{opacity:1;stroke-width:2.2}
#streams .packet{opacity:0;transition:opacity .3s}
#streams .packet.on{opacity:1}
@keyframes flow{to{stroke-dashoffset:-50}}

.panel{position:absolute;width:var(--pw,250px);z-index:2;border-radius:var(--r);padding:12px 14px 14px;background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.02));border:1px solid var(--line-2);backdrop-filter:blur(14px) saturate(130%);-webkit-backdrop-filter:blur(14px) saturate(130%);box-shadow:0 30px 60px -30px rgba(0,0,0,.9),inset 0 1px 0 rgba(255,255,255,.08);transition:border-color .45s,box-shadow .45s,transform .6s cubic-bezier(.2,.8,.2,1),opacity .45s;opacity:.62;will-change:transform}
.panel.on{opacity:1;border-color:rgba(121,166,255,.6);box-shadow:0 30px 70px -30px rgba(0,0,0,.9),0 0 0 1px rgba(139,92,255,.25),0 0 40px -6px rgba(61,123,255,.45),inset 0 1px 0 rgba(255,255,255,.14)}
.panel.done{opacity:.9}
.panel header{display:flex;align-items:center;gap:8px;margin-bottom:10px;font:500 11px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.panel header svg{width:14px;height:14px;color:var(--ink)}
.panel header .st{margin-left:auto;display:flex;align-items:center;gap:6px;color:var(--ink-4);letter-spacing:.08em}
.panel header .st::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--ink-4)}
.panel.on header .st{color:var(--blue-hi)}
.panel.on header .st::before{background:var(--blue-hi);box-shadow:0 0 10px var(--blue)}
.panel.done header .st::before{background:#fff}
.panel .body{height:96px;position:relative;overflow:hidden;border-radius:10px}
.p-code{left:3%;top:4%}.p-tex{left:6%;top:37%}.p-snd{left:1.5%;top:70%}
.p-3d{right:3%;top:4%}.p-build{right:6%;top:37%}.p-deploy{right:1.5%;top:70%}
.code{margin:0;font:400 11.5px/1.62 var(--mono);color:var(--ink-3);white-space:pre}
.code .k{color:var(--violet-hi)}.code .s{color:var(--blue-hi)}.code .c{color:var(--ink-4)}.code .w{color:#fff}
.tex-body{display:flex;gap:12px;align-items:center}
.tex-body canvas{width:96px;height:96px;image-rendering:pixelated;border-radius:6px;background:repeating-conic-gradient(rgba(255,255,255,.05) 0 25%,transparent 0 50%) 0 0/12px 12px}
.swatches{display:grid;grid-template-columns:repeat(3,16px);gap:6px}
.swatches i{width:16px;height:16px;border-radius:4px;display:block;box-shadow:inset 0 0 0 1px rgba(255,255,255,.15)}
.p-3d canvas,.p-snd canvas{width:100%;height:96px}
.build-bar{height:4px;border-radius:4px;background:rgba(255,255,255,.08);overflow:hidden;margin:4px 0 10px}
.build-bar i{display:block;height:100%;width:0;background:var(--energy);box-shadow:0 0 12px var(--blue)}
.log{margin:0;padding:0;list-style:none;font:400 11px/1.75 var(--mono);color:var(--ink-3)}
.log li{opacity:0;transform:translateY(4px);transition:opacity .3s,transform .3s}
.log li.in{opacity:1;transform:none}
.log li b{color:#fff;font-weight:500}
.srv{display:flex;align-items:center;gap:10px;padding:10px;border-radius:10px;background:rgba(255,255,255,.04);border:1px solid var(--line)}
.srv .ic{width:30px;height:30px;border-radius:8px;display:grid;place-items:center;background:#111;border:1px solid var(--line-2)}
.srv .ic img{width:18px;height:18px}
.srv b{display:block;font:600 13px var(--display)}
.srv small{display:block;font:400 11px var(--mono);color:var(--ink-3)}
.srv .dot{margin-left:auto;width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 8px rgba(255,255,255,.7)}
.inst{margin-top:8px;display:flex;align-items:center;gap:8px;font:400 11px var(--mono);color:var(--ink-3);opacity:.35;transition:opacity .4s}
.inst.in{opacity:1;color:#fff}
.inst svg{width:14px;height:14px;color:var(--blue-hi)}

.hero-copy{position:relative;z-index:5;text-align:center;margin-top:-10px;padding:0 var(--gut)}
.eyebrow{display:inline-flex;align-items:center;gap:10px;font:500 11px var(--mono);letter-spacing:.24em;text-transform:uppercase;color:var(--ink-3)}
.eyebrow::before{content:"";width:22px;height:1px;background:var(--energy)}
h1{font:600 clamp(34px,4.6vw,64px)/1.02 var(--display);letter-spacing:-.035em;margin:12px 0 0}
h1 em{font-style:normal;color:var(--ink-4)}

/* prompt */
.prompt{position:relative;z-index:6;max-width:860px;margin:26px auto 0;border-radius:24px;padding:1px;background:linear-gradient(140deg,rgba(255,255,255,.28),rgba(255,255,255,.06) 40%,rgba(139,92,255,.35));box-shadow:0 40px 100px -40px rgba(61,123,255,.55)}
.prompt-in{border-radius:23px;background:rgba(8,8,12,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);padding:14px}
.prompt-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.chip-btn{display:inline-flex;align-items:center;gap:8px;height:34px;padding:0 12px;border-radius:999px;border:1px solid var(--line-2);background:rgba(255,255,255,.04);font-size:13px;color:var(--ink-2);transition:border-color .2s,background .2s,color .2s}
.chip-btn:hover{border-color:rgba(255,255,255,.35);color:#fff}
.chip-btn img{width:16px;height:16px}
.chip-btn svg{width:12px;height:12px}
.chip-btn[aria-expanded=true]{border-color:var(--blue-hi);color:#fff}
.game-pick{position:relative}
.menu{position:absolute;top:calc(100% + 8px);left:0;z-index:20;min-width:240px;padding:6px;border-radius:14px;background:rgba(14,14,20,.96);border:1px solid var(--line-2);box-shadow:0 30px 60px -20px #000;list-style:none;margin:0}
.menu[hidden]{display:none}
.menu li button,.menu li span{display:flex;align-items:center;gap:10px;width:100%;padding:9px 10px;border-radius:9px;border:0;background:none;text-align:left;font-size:14px;color:var(--ink-2)}
.menu li button:hover,.menu li button:focus-visible{background:rgba(255,255,255,.07);color:#fff}
.menu li span{color:var(--ink-4);cursor:not-allowed}
.menu .tag{margin-left:auto;font:500 10px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-4);border:1px solid var(--line-2);border-radius:999px;padding:2px 7px}
.menu .tag.live{color:#fff;border-color:rgba(121,166,255,.6)}
.prompt-hint{margin-left:auto;font:400 11px var(--mono);color:var(--ink-4);letter-spacing:.06em}
.prompt textarea{display:block;width:100%;resize:none;border:0;background:transparent;outline:none;padding:14px 6px 10px;min-height:76px;font:500 clamp(17px,1.7vw,21px)/1.45 var(--display);letter-spacing:-.01em;color:#fff}
.prompt textarea::placeholder{color:var(--ink-4)}
.prompt textarea:focus-visible{outline:none}
.prompt-in:focus-within{box-shadow:inset 0 0 0 1px rgba(121,166,255,.35);border-radius:23px}
.caret{display:inline-block;width:2px;height:1.1em;background:var(--blue-hi);vertical-align:-.15em;animation:blink 1s steps(1) infinite}
@keyframes blink{50%{opacity:0}}
.prompt-bot{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.adv{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:12px 4px 14px;border-top:1px solid var(--line);margin-top:4px}
.adv[hidden]{display:none}
.adv label,.adv fieldset{font:500 11px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3);border:0;margin:0;padding:0;min-width:0}
.adv select{display:block;width:100%;margin-top:6px;height:36px;border-radius:10px;border:1px solid var(--line-2);background:#0c0c11;padding:0 10px;font:400 13px var(--body);letter-spacing:0;text-transform:none;color:#fff}
.toggles{display:flex;gap:6px;margin-top:6px;flex-wrap:wrap}
.toggles label{display:inline-flex;align-items:center;gap:6px;height:36px;padding:0 10px;border-radius:10px;border:1px solid var(--line-2);font:400 13px var(--body);text-transform:none;letter-spacing:0;color:var(--ink-2);cursor:pointer}
.toggles input{accent-color:var(--blue)}
.stages{display:flex;gap:4px;align-items:center;flex:1;min-width:0;overflow-x:auto;scrollbar-width:none}
.stages::-webkit-scrollbar{display:none}
.stg{display:flex;align-items:center;gap:6px;height:30px;padding:0 10px;border-radius:999px;font:500 11px var(--mono);letter-spacing:.06em;color:var(--ink-4);white-space:nowrap;border:1px solid transparent;transition:color .3s,border-color .3s,background .3s}
.stg i{width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.6;transition:background .3s,box-shadow .3s}
.stg.on{color:#fff;border-color:rgba(121,166,255,.55);background:rgba(61,123,255,.12)}
.stg.on i{background:var(--blue-hi);box-shadow:0 0 10px var(--blue);opacity:1}
.stg.done{color:var(--ink-2)}
.stg.done i{background:#fff;opacity:1}
.hero-foot{display:flex;justify-content:center;gap:12px;margin:22px 0 0;padding-bottom:48px;position:relative;z-index:5}
.hero-panels-m{display:none}

/* ---------- sections ---------- */
section{position:relative}
.sec{padding:clamp(80px,12vw,150px) 0}
.sec-head{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:24px;margin-bottom:clamp(36px,5vw,64px)}
.sec-idx{font:500 11px var(--mono);letter-spacing:.24em;text-transform:uppercase;color:var(--ink-3);display:flex;align-items:center;gap:12px}
.sec-idx b{color:#fff;font-weight:500}
.sec-idx::after{content:"";width:40px;height:1px;background:var(--line-2)}
h2{font:600 clamp(30px,4.2vw,56px)/1.04 var(--display);letter-spacing:-.035em;margin:14px 0 0;max-width:16ch}
h2 em{font-style:normal;color:var(--ink-4)}
.sec-head p{margin:0;max-width:34ch;color:var(--ink-3);font-size:15px}
h3{font:600 20px/1.2 var(--display);letter-spacing:-.02em;margin:0}

.reveal{opacity:0;transform:translateY(26px);transition:opacity .9s cubic-bezier(.2,.8,.2,1),transform .9s cubic-bezier(.2,.8,.2,1);transition-delay:var(--d,0s)}
.reveal.in{opacity:1;transform:none}

/* pipeline */
.pipe{position:relative;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:12px}
.pipe-line{position:absolute;left:calc(100%/14);right:calc(100%/14);top:46px;height:1px;background:var(--line-2);overflow:hidden}
.pipe-line i{position:absolute;top:0;left:0;height:1px;width:0;background:var(--energy);box-shadow:0 0 12px var(--blue);transition:width 1.8s cubic-bezier(.4,0,.2,1)}
.pipe.in .pipe-line i{width:100%}
.pipe-line b{position:absolute;top:-2px;left:0;width:80px;height:5px;border-radius:5px;background:linear-gradient(90deg,transparent,#fff,transparent);opacity:0;animation:pulse-run 3.6s 1.8s cubic-bezier(.5,0,.5,1) infinite}
.pipe.in .pipe-line b{opacity:1}
@keyframes pulse-run{from{transform:translateX(-80px)}to{transform:translateX(calc(100vw))}}
.step{position:relative;text-align:center;padding:0 4px}
.step .node{position:relative;width:92px;height:92px;margin:0 auto 18px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle at 50% 35%,rgba(255,255,255,.08),rgba(0,0,0,.9) 70%);border:1px solid var(--line-2);transition:transform .5s cubic-bezier(.2,.8,.2,1),border-color .4s,box-shadow .4s}
.step .node::before{content:"";position:absolute;inset:-7px;border-radius:50%;border:1px dashed rgba(255,255,255,.12);animation:rot 24s linear infinite}
.step .node svg{width:34px;height:34px;color:#fff}
.step:hover .node{transform:translateY(-4px);border-color:rgba(121,166,255,.7);box-shadow:0 0 40px -8px var(--blue)}
.step .n{font:500 10px var(--mono);letter-spacing:.2em;color:var(--ink-4)}
.step h3{font-size:17px;margin:4px 0 6px}
.step p{margin:0;font-size:13px;color:var(--ink-3);line-height:1.45}
@keyframes rot{to{transform:rotate(360deg)}}

/* studios bento */
.bento{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px}
.card{position:relative;border-radius:22px;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.015));border:1px solid var(--line);padding:22px;overflow:hidden;transition:border-color .4s,transform .5s cubic-bezier(.2,.8,.2,1)}
.card::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:radial-gradient(500px circle at var(--mx,50%) var(--my,0%),rgba(121,166,255,.10),transparent 45%);opacity:0;transition:opacity .4s}
.card:hover{border-color:var(--line-2)}
.card:hover::before{opacity:1}
.card-h{display:flex;align-items:center;gap:12px;margin-bottom:18px}
.card-h .glyph{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;border:1px solid var(--line-2);background:rgba(255,255,255,.03)}
.card-h .glyph svg{width:18px;height:18px}
.card-h small{display:block;font:500 10px var(--mono);letter-spacing:.2em;text-transform:uppercase;color:var(--ink-4)}
.card-h .aside{margin-left:auto;font:400 12px var(--mono);color:var(--ink-4)}
.c-tex{grid-column:span 5}.c-3d{grid-column:span 7}.c-snd{grid-column:span 6}.c-cfg{grid-column:span 6}.c-mot{grid-column:span 12}
.tool-row{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.tbtn{height:34px;min-width:34px;padding:0 10px;border-radius:10px;border:1px solid var(--line-2);background:rgba(255,255,255,.03);display:inline-flex;align-items:center;justify-content:center;gap:6px;font-size:13px;color:var(--ink-2);transition:all .2s}
.tbtn:hover{color:#fff;border-color:rgba(255,255,255,.35)}
.tbtn[aria-pressed=true]{color:#fff;border-color:var(--blue-hi);background:rgba(61,123,255,.16)}
.tbtn svg{width:15px;height:15px}
.paint{display:grid;grid-template-columns:minmax(0,1fr) 112px;gap:16px;align-items:start;margin-top:14px}
#paint{width:100%;aspect-ratio:1;image-rendering:pixelated;border-radius:12px;cursor:crosshair;touch-action:none;background:repeating-conic-gradient(#121218 0 25%,#0a0a0e 0 50%) 0 0/12.5% 12.5%;border:1px solid var(--line-2)}
.pal{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.pal button{aspect-ratio:1;border-radius:8px;border:1px solid rgba(255,255,255,.12);padding:0;transition:transform .15s}
.pal button:hover{transform:scale(1.08)}
.pal button[aria-pressed=true]{box-shadow:0 0 0 2px #000,0 0 0 4px #fff}
.mini{margin-top:14px;text-align:center}
.mini canvas{width:112px;height:112px;margin:0 auto;border-radius:12px;background:radial-gradient(circle at 50% 70%,rgba(61,123,255,.18),transparent 70%),#07070b;border:1px solid var(--line)}
.mini small{display:block;margin-top:6px;font:400 11px var(--mono);color:var(--ink-4)}

.viewer{position:relative;height:clamp(300px,34vw,420px);border-radius:16px;background:radial-gradient(ellipse at 50% 80%,rgba(61,123,255,.14),transparent 60%),radial-gradient(ellipse at 50% 20%,rgba(139,92,255,.08),transparent 60%),#050508;border:1px solid var(--line);overflow:hidden;touch-action:none}
.viewer canvas{width:100%!important;height:100%!important;cursor:grab}
.viewer canvas:active{cursor:grabbing}
.viewer .vstate{position:absolute;inset:0;display:grid;place-items:center;font:400 12px var(--mono);color:var(--ink-3);pointer-events:none}
.viewer .vstate img{max-width:80%;opacity:.8;border-radius:12px}
.viewer .vhint{position:absolute;left:14px;bottom:12px;font:400 11px var(--mono);color:var(--ink-4);pointer-events:none}
.viewer .vtri{position:absolute;right:14px;bottom:12px;font:400 11px var(--mono);color:var(--ink-4);pointer-events:none}
.seg{display:inline-flex;padding:3px;border-radius:999px;border:1px solid var(--line-2);background:rgba(255,255,255,.03);gap:2px;flex-wrap:wrap}
.seg button{height:30px;padding:0 13px;border-radius:999px;border:0;background:transparent;color:var(--ink-3);font-size:13px;transition:background .25s,color .25s}
.seg button:hover{color:#fff}
.seg button[aria-pressed=true]{background:#fff;color:#000}

.wave-wrap{position:relative;height:150px;border-radius:14px;background:#050508;border:1px solid var(--line);overflow:hidden;cursor:pointer;touch-action:none}
#wave{width:100%;height:100%}
.ph{position:absolute;top:0;bottom:0;left:0;width:1px;background:#fff;box-shadow:0 0 12px var(--blue-hi);pointer-events:none}
.snd-row{display:flex;gap:10px;align-items:center;margin-top:14px;flex-wrap:wrap}
.play{width:46px;height:46px;border-radius:50%;border:0;background:#fff;color:#000;display:grid;place-items:center;flex:none;transition:transform .2s,box-shadow .3s}
.play:hover{box-shadow:0 0 30px -4px var(--blue)}
.play svg{width:18px;height:18px}
.time{font:400 12px var(--mono);color:var(--ink-3);margin-left:auto}

.walk{position:relative;height:170px;border-radius:14px;background:#050508;border:1px solid var(--line);overflow:hidden}
#walker{width:100%;height:100%}
.sliders{display:grid;gap:12px;margin-top:16px}
.sl{display:grid;grid-template-columns:110px minmax(0,1fr) 54px;align-items:center;gap:12px;font-size:13px;color:var(--ink-2)}
.sl output{font:500 12px var(--mono);text-align:right;color:#fff}
input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:24px;background:transparent;cursor:pointer}
input[type=range]::-webkit-slider-runnable-track{height:3px;border-radius:3px;background:linear-gradient(90deg,var(--blue) 0,var(--violet) var(--p,50%),rgba(255,255,255,.12) var(--p,50%))}
input[type=range]::-moz-range-track{height:3px;border-radius:3px;background:rgba(255,255,255,.12)}
input[type=range]::-moz-range-progress{height:3px;background:var(--energy)}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;border-radius:50%;background:#fff;margin-top:-7.5px;box-shadow:0 0 0 4px rgba(61,123,255,.25)}
input[type=range]::-moz-range-thumb{width:18px;height:18px;border:0;border-radius:50%;background:#fff;box-shadow:0 0 0 4px rgba(61,123,255,.25)}
input[type=range]:focus-visible{outline:none}
input[type=range]:focus-visible::-webkit-slider-thumb{box-shadow:0 0 0 4px var(--blue-hi)}
.cfg-json{margin:14px 0 0;padding:12px 14px;border-radius:12px;background:#050508;border:1px solid var(--line);font:400 12px/1.6 var(--mono);color:var(--ink-3);overflow-x:auto}
.cfg-json b{color:var(--blue-hi);font-weight:400}

.loops{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.loop{position:relative;border-radius:14px;overflow:hidden;border:1px solid var(--line);background:#06070c;padding:0;text-align:left;color:inherit;transition:border-color .3s,transform .4s cubic-bezier(.2,.8,.2,1)}
.loop:hover{border-color:var(--line-2);transform:translateY(-3px)}
.loop .spr{aspect-ratio:var(--ar,4/3);background-repeat:no-repeat;background-size:calc(var(--n)*100%) 100%;background-position:0 0}
.loop.fx .spr{aspect-ratio:1;background-color:#000;mix-blend-mode:screen;image-rendering:auto}
.loop .lab{display:flex;align-items:center;gap:8px;padding:10px 12px;border-top:1px solid var(--line);font:500 11px var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3)}
.loop .lab .pp{margin-left:auto;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;border:1px solid var(--line-2)}
.loop .lab .pp svg{width:9px;height:9px}
.loops.fxrow{grid-template-columns:repeat(4,minmax(0,1fr));margin-top:12px}

/* mods in game */
.mods{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.mod{border-radius:22px;border:1px solid var(--line);overflow:hidden;background:#050508;transition:transform .6s cubic-bezier(.2,.8,.2,1),border-color .4s;transform-style:preserve-3d}
.mod:hover{border-color:var(--line-2)}
.scene{position:relative;aspect-ratio:4/3.3;overflow:hidden}
.scene canvas.world{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated}
.scene .item{position:absolute;inset:6% 8% 10%;width:84%;height:84%;object-fit:contain;mask-image:radial-gradient(closest-side,#000 62%,transparent 100%);-webkit-mask-image:radial-gradient(closest-side,#000 62%,transparent 100%);transition:opacity .5s,transform .7s cubic-bezier(.2,.8,.2,1);filter:drop-shadow(0 18px 24px rgba(0,0,0,.6))}
.scene .item.off{opacity:0;transform:scale(.94) translateY(8px)}
.scene canvas.drop{position:absolute;left:50%;top:50%;width:46%;height:46%;transform:translate(-50%,-56%);image-rendering:pixelated}
.hud{position:absolute;left:50%;bottom:10px;transform:translateX(-50%);display:flex;gap:2px;padding:3px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.18)}
.hud i{width:22px;height:22px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.04)}
.hud i.sel{border-color:#fff;box-shadow:inset 0 0 0 1px #fff}
.mod-f{display:flex;align-items:center;gap:12px;padding:16px 18px;border-top:1px solid var(--line);flex-wrap:wrap}
.mod-f h3{font-size:16px}
.mod-f small{display:block;font:400 11px var(--mono);color:var(--ink-4);margin-top:2px}
.mod-f .seg{margin-left:auto}

/* games */
.games{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:16px;align-items:stretch}
.mc{position:relative;border-radius:22px;padding:28px;border:1px solid rgba(121,166,255,.35);background:radial-gradient(ellipse at 30% 0%,rgba(61,123,255,.18),transparent 60%),radial-gradient(ellipse at 100% 100%,rgba(139,92,255,.16),transparent 60%),#06060a;overflow:hidden;display:flex;flex-direction:column;min-height:360px}
.mc img{width:84px;height:auto;filter:drop-shadow(0 20px 30px rgba(61,123,255,.35))}
.mc h3{font-size:clamp(28px,3vw,40px);letter-spacing:-.03em;margin-top:auto}
.live{display:inline-flex;align-items:center;gap:8px;font:500 11px var(--mono);letter-spacing:.2em;text-transform:uppercase;color:#fff;margin-top:14px}
.live::before{content:"";width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 0 0 rgba(255,255,255,.6);animation:ping 2s infinite}
@keyframes ping{0%{box-shadow:0 0 0 0 rgba(121,166,255,.7)}100%{box-shadow:0 0 0 12px rgba(121,166,255,0)}}
.mc .btn{align-self:flex-start;margin-top:22px}
.soon{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.g{position:relative;border-radius:18px;border:1px solid var(--line);background:#07070b;aspect-ratio:1/1.05;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:14px;overflow:hidden;text-align:center}
.g .gi{width:56%;aspect-ratio:1;display:grid;place-items:center}
.g .gi img{max-width:100%;max-height:100%;object-fit:contain;filter:grayscale(1) brightness(.85) contrast(1.05);opacity:.75;transition:filter .5s,opacity .5s,transform .6s cubic-bezier(.2,.8,.2,1)}
.g:hover .gi img{filter:none;opacity:1;transform:scale(1.06)}
.g .mono-ph{width:100%;aspect-ratio:1;border-radius:18px;border:1px solid var(--line-2);display:grid;place-items:center;font:600 clamp(18px,2vw,26px) var(--display);letter-spacing:-.02em;color:var(--ink-3);background:repeating-linear-gradient(135deg,rgba(255,255,255,.025) 0 6px,transparent 6px 12px)}
.g:hover .mono-ph{color:#fff;border-color:rgba(255,255,255,.3)}
.g b{font:600 14px var(--display)}
.g small{position:absolute;top:10px;right:10px;font:500 9px var(--mono);letter-spacing:.16em;text-transform:uppercase;color:var(--ink-4);border:1px solid var(--line-2);border-radius:999px;padding:2px 7px}

/* plans */
.plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.plan{position:relative;border-radius:24px;padding:28px 26px 26px;border:1px solid var(--line);background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.01));display:flex;flex-direction:column;overflow:hidden;transition:transform .6s cubic-bezier(.2,.8,.2,1),border-color .4s}
.plan:hover{transform:translateY(-6px);border-color:var(--line-2)}
.plan::after{content:"";position:absolute;left:-20%;right:-20%;top:-60%;height:80%;background:radial-gradient(closest-side,var(--tint),transparent);opacity:.18;pointer-events:none;transition:opacity .5s}
.plan:hover::after{opacity:.32}
.plan.katara{--tint:#3d7bff}.plan.saka{--tint:#6a6cff}.plan.yakko{--tint:#8b5cff}
.plan .sig{width:96px;height:96px;margin-bottom:22px}
.plan .tier{font:500 10px var(--mono);letter-spacing:.22em;text-transform:uppercase;color:var(--ink-4)}
.plan h3{font-size:32px;letter-spacing:-.03em;margin:6px 0 4px}
.plan .lead{margin:0 0 20px;color:var(--ink-2);font-size:15px}
.plan ul{list-style:none;margin:0 0 26px;padding:0;display:grid;gap:10px;font-size:14px;color:var(--ink-2)}
.plan li{display:flex;gap:10px;align-items:flex-start}
.plan li svg{flex:none;width:16px;height:16px;margin-top:2px;color:var(--blue-hi)}
.plan li.dim{color:var(--ink-4)}
.plan li.dim svg{color:var(--ink-4)}
.plan .btn{margin-top:auto}
.plan.yakko{border-color:rgba(139,92,255,.35)}
.free{margin-top:16px;border-radius:18px;border:1px dashed var(--line-2);padding:16px 22px;display:flex;align-items:center;gap:16px;flex-wrap:wrap;color:var(--ink-2);font-size:15px}
.free b{font:600 16px var(--display);color:#fff}
.free .btn{margin-left:auto}

/* plan icons */
.sig .w1{animation:wave 5s linear infinite}.sig .w2{animation:wave 3.4s linear infinite reverse}.sig .w3{animation:wave 7s linear infinite}
@keyframes wave{to{transform:translateX(-48px)}}
.sig .bob{animation:bob 4s ease-in-out infinite;transform-origin:48px 48px}
@keyframes bob{50%{transform:translateY(-2px)}}
.sig .fl1{transform-origin:48px 78px;animation:flick 2.2s ease-in-out infinite}
.sig .fl2{transform-origin:48px 78px;animation:flick 1.7s ease-in-out infinite reverse}
.sig .fl3{transform-origin:48px 78px;animation:flick 1.3s ease-in-out infinite}
@keyframes flick{0%,100%{transform:scale(1,1) skewX(0)}30%{transform:scale(.97,1.05) skewX(-3deg)}65%{transform:scale(1.03,.96) skewX(3deg)}}
.sig .em{animation:rise 2.6s ease-in infinite;opacity:0}
.sig .em:nth-of-type(2){animation-delay:.9s}.sig .em:nth-of-type(3){animation-delay:1.7s}
@keyframes rise{0%{transform:translateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(-34px);opacity:0}}
.sig .r1{transform-origin:48px 48px;animation:rot 18s linear infinite}
.sig .r2{transform-origin:48px 48px;animation:rot 12s linear infinite reverse}
.sig .spark{transform-origin:48px 48px;animation:spark 2.8s ease-in-out infinite}
@keyframes spark{0%,100%{transform:scale(.86) rotate(0);opacity:.85}50%{transform:scale(1.08) rotate(45deg);opacity:1}}

/* bridge */
.bridge{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:clamp(24px,4vw,64px);align-items:center}
.bridge-copy .btn-nx{margin-top:26px;--h:52px;padding:0 22px 0 14px;background:#0b0b10;border-color:rgba(255,255,255,.22)}
.bridge-copy .btn-nx img{height:20px;width:auto}
.bridge-copy .btn-nx:hover{border-color:rgba(121,166,255,.7);box-shadow:0 0 40px -10px var(--blue)}
.feats{list-style:none;margin:28px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:18px 22px}
.feats li{display:flex;gap:12px;align-items:flex-start;font-size:14px;color:var(--ink-3)}
.feats li b{display:block;color:#fff;font:600 15px var(--display);margin-bottom:2px}
.feats svg{flex:none;width:20px;height:20px;margin-top:2px;color:var(--blue-hi)}
.key{margin-top:28px;display:flex;gap:8px;align-items:stretch;flex-wrap:wrap}
.key label{width:100%;font:500 11px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.key input{flex:1;min-width:0;height:46px;border-radius:12px;border:1px solid var(--line-2);background:#07070b;padding:0 14px;font:400 14px var(--mono);color:#fff}
.key input::placeholder{color:var(--ink-4)}
.key input:focus-visible{outline:2px solid var(--blue-hi);outline-offset:1px}
.link-viz{position:relative;border-radius:26px;border:1px solid var(--line);background:radial-gradient(ellipse at 50% 30%,rgba(61,123,255,.10),transparent 60%),#040406;padding:clamp(18px,3vw,34px);overflow:hidden}
.link-viz svg.lnk{width:100%;height:auto;overflow:visible}
.srv-card{margin:0 auto;max-width:440px;border-radius:18px;border:1px solid var(--line-2);background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.015));padding:16px;backdrop-filter:blur(10px)}
.srv-card .top{display:flex;align-items:center;gap:12px}
.srv-card .top .ic{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#0d0d12;border:1px solid var(--line-2)}
.srv-card .top .ic img{width:24px}
.srv-card .top b{font:600 15px var(--display);display:block}
.srv-card .top small{font:400 12px var(--mono);color:var(--ink-3)}
.srv-card .top .on{margin-left:auto;display:flex;align-items:center;gap:6px;font:500 11px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-2)}
.srv-card .top .on::before{content:"";width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 10px #fff}
.modlist{list-style:none;margin:14px 0 0;padding:0;display:grid;gap:6px}
.modlist li{display:flex;align-items:center;gap:10px;height:40px;padding:0 12px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid var(--line);font:400 13px var(--mono);color:var(--ink-2)}
.modlist li span{margin-left:auto;font-size:11px;color:var(--ink-4);letter-spacing:.08em;text-transform:uppercase}
.modlist li.new{border-color:rgba(121,166,255,.6);color:#fff;background:rgba(61,123,255,.1);animation:slidein 6s cubic-bezier(.2,.8,.2,1) infinite}
.modlist li.new span{color:var(--blue-hi)}
@keyframes slidein{0%,30%{opacity:0;transform:translateY(-14px) scale(.97)}42%,92%{opacity:1;transform:none}100%{opacity:0}}
.lnk .travel{offset-path:path("M120 60 C 230 60, 330 60, 440 60");animation:travel 6s cubic-bezier(.6,0,.3,1) infinite}
@keyframes travel{0%{offset-distance:0%;opacity:0}6%{opacity:1}30%{offset-distance:100%;opacity:1}34%,100%{offset-distance:100%;opacity:0}}
.lnk .dash{stroke-dasharray:2 8;animation:flow 1.4s linear infinite}

/* final cta */
.final{text-align:center;padding:clamp(100px,14vw,180px) 0 clamp(80px,10vw,140px);overflow:hidden}
.final .halo{position:absolute;left:50%;top:50%;width:min(760px,130vw);aspect-ratio:1;transform:translate(-50%,-50%);pointer-events:none;z-index:-1}
.final .halo i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(255,255,255,.07)}
.final .halo i:nth-child(2){inset:12%;border-color:rgba(121,166,255,.14);border-style:dashed;animation:rot 60s linear infinite}
.final .halo i:nth-child(3){inset:26%;border-color:rgba(139,92,255,.18)}
.final .halo i:nth-child(4){inset:38%;border:0;background:radial-gradient(circle at 45% 40%,#fff 0,#a9c3ff 8%,var(--blue) 26%,var(--violet) 48%,transparent 70%);filter:blur(6px);opacity:.55;animation:breathe 6s ease-in-out infinite}
@keyframes breathe{50%{transform:scale(1.06);opacity:.7}}
.final h2{margin:18px auto 0;max-width:14ch;font-size:clamp(38px,6vw,84px)}
.final .ctas{display:flex;gap:12px;justify-content:center;margin-top:36px;flex-wrap:wrap}

/* footer */
footer{border-top:1px solid var(--line);padding:40px 0 48px}
footer .wrap{display:flex;align-items:center;gap:24px;flex-wrap:wrap}
footer .brand img{height:20px}
.byline{display:flex;align-items:center;gap:12px;font:500 11px var(--mono);letter-spacing:.2em;text-transform:uppercase;color:var(--ink-3);text-decoration:none}
.byline img{height:22px;width:auto}
footer nav{margin-left:auto;display:flex;gap:18px;flex-wrap:wrap}
footer nav a{color:var(--ink-3);text-decoration:none;font-size:14px}
footer nav a:hover{color:#fff}
footer .copy{width:100%;font:400 12px var(--mono);color:var(--ink-4)}

.toast{position:fixed;left:50%;bottom:24px;z-index:90;transform:translate(-50%,30px);opacity:0;pointer-events:none;padding:12px 18px;border-radius:14px;background:rgba(16,16,22,.95);border:1px solid var(--line-2);font-size:14px;color:#fff;box-shadow:0 20px 50px -10px #000;transition:all .4s cubic-bezier(.2,.8,.2,1);max-width:calc(100vw - 32px);text-align:center}
.toast.show{opacity:1;transform:translate(-50%,0)}

/* ---------- responsive ---------- */
@media (max-width:1180px){
  .panel{--pw:212px}
  .p-code,.p-3d{top:2%}
  .c-tex,.c-3d,.c-snd,.c-cfg{grid-column:span 12}
  .c-tex .paint{grid-template-columns:minmax(0,360px) 140px;justify-content:start}
  .loops{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:980px){
  .nav-links{display:none}
  .nav-cta .btn:not(.btn-solid){display:none}
  .menu-btn{display:grid;margin-left:auto}
  .nav-links.open{display:flex;position:absolute;top:68px;left:0;right:0;flex-direction:column;padding:12px var(--gut) 20px;background:rgba(0,0,0,.94);border-bottom:1px solid var(--line);backdrop-filter:blur(16px)}
  .nav-links.open a{font-size:17px;padding:12px 0;color:#fff;border-radius:0}
  .stage{height:min(78vw,400px)}
  .core{--core:min(84vw,400px)}
  .stage .panel,#streams{display:none}
  .hero-panels-m{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;padding:4px var(--gut) 8px;margin:18px 0 0;scrollbar-width:none;position:relative;z-index:5}
  .hero-panels-m::-webkit-scrollbar{display:none}
  .hero-panels-m .panel{position:relative;inset:auto;flex:0 0 232px;scroll-snap-align:center;--pw:232px}
  .pipe{grid-template-columns:minmax(0,1fr);gap:0}
  .pipe-line{left:45px;right:auto;top:20px;bottom:20px;width:1px;height:auto}
  .pipe-line i{width:1px!important;height:0;transition:height 1.8s cubic-bezier(.4,0,.2,1)}
  .pipe.in .pipe-line i{height:100%}
  .pipe-line b{display:none}
  .step{display:grid;grid-template-columns:92px minmax(0,1fr);gap:18px;text-align:left;align-items:center;padding:10px 0}
  .step .node{margin:0}
  .games,.bridge{grid-template-columns:minmax(0,1fr)}
  .plans{grid-template-columns:minmax(0,1fr);max-width:560px;margin:0 auto}
  .mods{grid-template-columns:minmax(0,1fr);max-width:560px;margin:0 auto}
  .sec-head{grid-template-columns:minmax(0,1fr)}
  .adv{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:640px){
  body{font-size:15px}
  .hero-copy{margin-top:0}
  .prompt{margin-left:12px;margin-right:12px;border-radius:20px}
  .prompt-in{border-radius:19px;padding:12px}
  .prompt-hint{display:none}
  .prompt-bot{flex-direction:column;align-items:stretch}
  .prompt-bot .btn-create{width:100%}
  .stages{order:2}
  .hero-foot{flex-direction:column;align-items:stretch;padding:0 var(--gut) 40px}
  .soon{grid-template-columns:repeat(2,minmax(0,1fr))}
  .loops,.loops.fxrow{grid-template-columns:repeat(2,minmax(0,1fr))}
  .c-tex .paint{grid-template-columns:minmax(0,1fr)}
  .c-tex .side{display:grid;grid-template-columns:minmax(0,1fr) 112px;gap:14px;align-items:start}
  .c-tex .mini{margin-top:0}
  .pal{grid-template-columns:repeat(6,1fr)}
  .card{padding:16px;border-radius:18px}
  .card-h .aside{display:none}
  .feats{grid-template-columns:minmax(0,1fr)}
  .sl{grid-template-columns:92px minmax(0,1fr) 46px;gap:8px}
  .mod-f .seg{margin-left:0}
  .free .btn{margin-left:0}
  footer nav{margin-left:0}
  .step{grid-template-columns:72px minmax(0,1fr)}
  .step .node{width:72px;height:72px}
  .step .node svg{width:28px;height:28px}
  .pipe-line{left:35px}
}

@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important;scroll-behavior:auto!important}
  .reveal{opacity:1;transform:none}
  .modlist li.new{animation:none;opacity:1}
  .lnk .travel{animation:none;offset-distance:100%;opacity:1}
  .sig *{animation:none!important}
  .em{opacity:.8!important}
}

toolu_01TLKp4Pudq5D9jgKioVesYH.content:
/* CYRUS landing v7: a black-and-white instrument language with electric blue + violet energy. */
@font-face{font-family:"Grotesk";src:url(../fonts/sg-500.woff2) format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:"Grotesk";src:url(../fonts/sg-600.woff2) format("woff2");font-weight:600 700;font-display:swap}
@font-face{font-family:"Inter";src:url(../fonts/inter-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Inter";src:url(../fonts/inter-600.woff2) format("woff2");font-weight:500 700;font-display:swap}
@font-face{font-family:"Mono";src:url(../fonts/jb-400.woff2) format("woff2");font-weight:400;font-display:swap}
@font-face{font-family:"Mono";src:url(../fonts/jb-500.woff2) format("woff2");font-weight:500 700;font-display:swap}

:root{
  --bg:#000;--ink:#fff;--ink-2:rgba(255,255,255,.74);--ink-3:rgba(255,255,255,.56);--ink-4:rgba(255,255,255,.34);
  --line:rgba(255,255,255,.09);--line-2:rgba(255,255,255,.16);
  --blue:#3d7bff;--blue-hi:#79a6ff;--violet:#8b5cff;--violet-hi:#b49bff;
  --glass:rgba(255,255,255,.035);--glass-2:rgba(255,255,255,.06);
  --energy:linear-gradient(100deg,var(--blue),var(--violet));
  --r:18px;--r-sm:12px;--gut:clamp(16px,4vw,48px);--max:1240px;
  --display:"Grotesk","Inter",system-ui,sans-serif;--body:"Inter",system-ui,sans-serif;--mono:"Mono",ui-monospace,monospace;
  color-scheme:dark;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 var(--body);-webkit-font-smoothing:antialiased;overflow-x:hidden}
img,svg,canvas{display:block;max-width:100%}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}
a{color:inherit}
::selection{background:var(--violet);color:#fff}
:focus-visible{outline:2px solid var(--blue-hi);outline-offset:3px;border-radius:6px}
.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.skip{position:fixed;left:16px;top:-60px;z-index:100;background:#fff;color:#000;padding:10px 14px;border-radius:10px;font-weight:600;text-decoration:none}
.skip:focus{top:12px}
.wrap{width:100%;max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
.mono{font-family:var(--mono);letter-spacing:.02em}
.grad-text{background:var(--energy);-webkit-background-clip:text;background-clip:text;color:transparent}

/* ---------- nav ---------- */
.nav{position:fixed;inset:0 0 auto 0;z-index:50;transition:background .4s,border-color .4s,backdrop-filter .4s;border-bottom:1px solid transparent}
.nav.scrolled{background:rgba(0,0,0,.62);backdrop-filter:blur(16px) saturate(140%);-webkit-backdrop-filter:blur(16px) saturate(140%);border-color:var(--line)}
.nav .wrap{display:flex;align-items:center;gap:28px;height:68px}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none}
.brand img{height:22px;width:auto}
.nav-links{display:flex;gap:4px;margin-left:auto;list-style:none;padding:0;margin-top:0;margin-bottom:0}
.nav-links a{display:block;padding:8px 12px;border-radius:999px;color:var(--ink-3);text-decoration:none;font-size:14px;transition:color .2s,background .2s}
.nav-links a:hover{color:var(--ink);background:var(--glass-2)}
.nav-cta{display:flex;gap:8px;align-items:center}
.menu-btn{display:none;margin-left:auto;background:none;border:1px solid var(--line-2);border-radius:999px;width:40px;height:40px;place-items:center}
.menu-btn span{display:block;width:16px;height:1.5px;background:#fff;margin:3px auto;transition:transform .3s}
.menu-btn[aria-expanded=true] span:first-child{transform:translateY(2.25px) rotate(45deg)}
.menu-btn[aria-expanded=true] span:last-child{transform:translateY(-2.25px) rotate(-45deg)}

/* ---------- buttons ---------- */
.btn{--h:44px;position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;height:var(--h);padding:0 20px;border-radius:999px;border:1px solid var(--line-2);background:transparent;color:var(--ink);font-weight:600;font-size:15px;text-decoration:none;white-space:nowrap;transition:transform .25s cubic-bezier(.2,.8,.2,1),background .25s,border-color .25s,box-shadow .3s}
.btn:hover{border-color:rgba(255,255,255,.4);background:var(--glass-2)}
.btn:active{transform:scale(.97)}
.btn-sm{--h:38px;padding:0 16px;font-size:14px}
.btn-lg{--h:54px;padding:0 28px;font-size:16px}
.btn-solid{background:#fff;color:#000;border-color:#fff}
.btn-solid:hover{background:#fff;border-color:#fff;box-shadow:0 0 0 1px rgba(255,255,255,.6),0 10px 40px -8px rgba(61,123,255,.75),0 10px 60px -10px rgba(139,92,255,.7)}
.btn-solid .arrow{transition:transform .3s}
.btn-solid:hover .arrow{transform:translateX(3px)}
.btn-create{--h:52px;padding:0 24px;background:#fff;color:#000;border:0;overflow:hidden;isolation:isolate}
.btn-create::before{content:"";position:absolute;inset:-2px;z-index:-1;background:conic-gradient(from var(--a,0deg),var(--blue),var(--violet),#fff,var(--blue));opacity:0;transition:opacity .35s}
.btn-create::after{content:"";position:absolute;inset:2px;z-index:-1;border-radius:inherit;background:#fff}
.btn-create:hover::before,.btn-create.busy::before{opacity:1;animation:spin 2.4s linear infinite}
.btn-create:hover{box-shadow:0 12px 50px -10px rgba(61,123,255,.8),0 12px 60px -12px rgba(139,92,255,.8)}
@property --a{syntax:"<angle>";inherits:false;initial-value:0deg}
@keyframes spin{to{--a:360deg}}

/* ---------- hero ---------- */
.hero{position:relative;min-height:100vh;min-height:100svh;padding-top:68px;overflow:hidden;isolation:isolate}
.hero-bg{position:absolute;inset:0;z-index:-2;pointer-events:none}
.hero-bg::before{content:"";position:absolute;left:50%;top:34%;width:1100px;height:1100px;transform:translate(-50%,-50%);background:radial-gradient(closest-side,rgba(61,123,255,.16),rgba(139,92,255,.06) 55%,transparent 72%)}
.hero-bg::after{content:"";position:absolute;inset:0;background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:64px 64px;mask-image:radial-gradient(ellipse 60% 55% at 50% 38%,#000 0%,transparent 75%);-webkit-mask-image:radial-gradient(ellipse 60% 55% at 50% 38%,#000 0%,transparent 75%);opacity:.45}
#particles{position:absolute;inset:0;width:100%;height:100%;z-index:-1}
.stage{position:relative;height:clamp(420px,56vh,540px);max-width:1320px;margin:0 auto}
.core{position:absolute;left:50%;top:50%;width:var(--core);height:var(--core);transform:translate(-50%,-50%);--core:min(520px,46vh)}
.core canvas{position:absolute;inset:0;width:100%;height:100%;mix-blend-mode:screen}
.rings{position:absolute;inset:-30%;width:160%;height:160%;overflow:visible;pointer-events:none}
.rings.front{z-index:3}
.rings ellipse,.rings path{fill:none}
.core-label{position:absolute;left:50%;bottom:4%;transform:translateX(-50%);font:500 11px var(--mono);letter-spacing:.24em;color:var(--ink-4);text-transform:uppercase;white-space:nowrap;z-index:4;transition:color .3s}
.core-label b{color:var(--ink);font-weight:500}
#streams{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;z-index:1}
#streams .base{stroke:rgba(255,255,255,.07);stroke-width:1;fill:none}
#streams .flow{fill:none;stroke-width:1.4;stroke-dasharray:1.5 11;stroke-linecap:round;opacity:.35;animation:flow 1.8s linear infinite;transition:opacity .4s,stroke-width .4s}
#streams .flow.on{opacity:1;stroke-width:2.2}
#streams .packet{opacity:0;transition:opacity .3s}
#streams .packet.on{opacity:1}
@keyframes flow{to{stroke-dashoffset:-50}}

.panel{position:absolute;width:var(--pw,250px);z-index:2;border-radius:var(--r);padding:12px 14px 14px;background:linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.02));border:1px solid var(--line-2);backdrop-filter:blur(14px) saturate(130%);-webkit-backdrop-filter:blur(14px) saturate(130%);box-shadow:0 30px 60px -30px rgba(0,0,0,.9),inset 0 1px 0 rgba(255,255,255,.08);transition:border-color .45s,box-shadow .45s,transform .6s cubic-bezier(.2,.8,.2,1),opacity .45s;opacity:.62;will-change:transform}
.panel.on{opacity:1;border-color:rgba(121,166,255,.6);box-shadow:0 30px 70px -30px rgba(0,0,0,.9),0 0 0 1px rgba(139,92,255,.25),0 0 40px -6px rgba(61,123,255,.45),inset 0 1px 0 rgba(255,255,255,.14)}
.panel.done{opacity:.9}
.panel header{display:flex;align-items:center;gap:8px;margin-bottom:10px;font:500 11px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.panel header svg{width:14px;height:14px;color:var(--ink)}
.panel header .st{margin-left:auto;display:flex;align-items:center;gap:6px;color:var(--ink-4);letter-spacing:.08em}
.panel header .st::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--ink-4)}
.panel.on header .st{color:var(--blue-hi)}
.panel.on header .st::before{background:var(--blue-hi);box-shadow:0 0 10px var(--blue)}
.panel.done header .st::before{background:#fff}
.panel .body{height:96px;position:relative;overflow:hidden;border-radius:10px}
.p-code{left:3%;top:4%}.p-tex{left:6%;top:37%}.p-snd{left:1.5%;top:70%}
.p-3d{right:3%;top:4%}.p-build{right:6%;top:37%}.p-deploy{right:1.5%;top:70%}
.code{margin:0;font:400 11.5px/1.62 var(--mono);color:var(--ink-3);white-space:pre}
.code .k{color:var(--violet-hi)}.code .s{color:var(--blue-hi)}.code .c{color:var(--ink-4)}.code .w{color:#fff}
.tex-body{display:flex;gap:12px;align-items:center}
.tex-body canvas{width:96px;height:96px;image-rendering:pixelated;border-radius:6px;background:repeating-conic-gradient(rgba(255,255,255,.05) 0 25%,transparent 0 50%) 0 0/12px 12px}
.swatches{display:grid;grid-template-columns:repeat(3,16px);gap:6px}
.swatches i{width:16px;height:16px;border-radius:4px;display:block;box-shadow:inset 0 0 0 1px rgba(255,255,255,.15)}
.p-3d canvas,.p-snd canvas{width:100%;height:96px}
.build-bar{height:4px;border-radius:4px;background:rgba(255,255,255,.08);overflow:hidden;margin:4px 0 10px}
.build-bar i{display:block;height:100%;width:0;background:var(--energy);box-shadow:0 0 12px var(--blue)}
.log{margin:0;padding:0;list-style:none;font:400 11px/1.75 var(--mono);color:var(--ink-3)}
.log li{opacity:0;transform:translateY(4px);transition:opacity .3s,transform .3s}
.log li.in{opacity:1;transform:none}
.log li b{color:#fff;font-weight:500}
.srv{display:flex;align-items:center;gap:10px;padding:10px;border-radius:10px;background:rgba(255,255,255,.04);border:1px solid var(--line)}
.srv .ic{width:30px;height:30px;border-radius:8px;display:grid;place-items:center;background:#111;border:1px solid var(--line-2)}
.srv .ic img{width:18px;height:18px}
.srv b{display:block;font:600 13px var(--display)}
.srv small{display:block;font:400 11px var(--mono);color:var(--ink-3)}
.srv .dot{margin-left:auto;width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 8px rgba(255,255,255,.7)}
.inst{margin-top:8px;display:flex;align-items:center;gap:8px;font:400 11px var(--mono);color:var(--ink-3);opacity:.35;transition:opacity .4s}
.inst.in{opacity:1;color:#fff}
.inst svg{width:14px;height:14px;color:var(--blue-hi)}

.hero-copy{position:relative;z-index:5;text-align:center;margin-top:-10px;padding:0 var(--gut)}
.eyebrow{display:inline-flex;align-items:center;gap:10px;font:500 11px var(--mono);letter-spacing:.24em;text-transform:uppercase;color:var(--ink-3)}
.eyebrow::before{content:"";width:22px;height:1px;background:var(--energy)}
h1{font:600 clamp(34px,4.6vw,64px)/1.02 var(--display);letter-spacing:-.035em;margin:12px 0 0}
h1 em{font-style:normal;color:var(--ink-4)}

/* prompt */
.prompt{position:relative;z-index:6;max-width:860px;margin:26px auto 0;border-radius:24px;padding:1px;background:linear-gradient(140deg,rgba(255,255,255,.28),rgba(255,255,255,.06) 40%,rgba(139,92,255,.35));box-shadow:0 40px 100px -40px rgba(61,123,255,.55)}
.prompt-in{border-radius:23px;background:rgba(8,8,12,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);padding:14px}
.prompt-top{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.chip-btn{display:inline-flex;align-items:center;gap:8px;height:34px;padding:0 12px;border-radius:999px;border:1px solid var(--line-2);background:rgba(255,255,255,.04);font-size:13px;color:var(--ink-2);transition:border-color .2s,background .2s,color .2s}
.chip-btn:hover{border-color:rgba(255,255,255,.35);color:#fff}
.chip-btn img{width:16px;height:16px}
.chip-btn svg{width:12px;height:12px}
.chip-btn[aria-expanded=true]{border-color:var(--blue-hi);color:#fff}
.game-pick{position:relative}
.menu{position:absolute;top:calc(100% + 8px);left:0;z-index:20;min-width:240px;padding:6px;border-radius:14px;background:rgba(14,14,20,.96);border:1px solid var(--line-2);box-shadow:0 30px 60px -20px #000;list-style:none;margin:0}
.menu[hidden]{display:none}
.menu li button,.menu li span{display:flex;align-items:center;gap:10px;width:100%;padding:9px 10px;border-radius:9px;border:0;background:none;text-align:left;font-size:14px;color:var(--ink-2)}
.menu li button:hover,.menu li button:focus-visible{background:rgba(255,255,255,.07);color:#fff}
.menu li span{color:var(--ink-4);cursor:not-allowed}
.menu .tag{margin-left:auto;font:500 10px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-4);border:1px solid var(--line-2);border-radius:999px;padding:2px 7px}
.menu .tag.live{color:#fff;border-color:rgba(121,166,255,.6)}
.prompt-hint{margin-left:auto;font:400 11px var(--mono);color:var(--ink-4);letter-spacing:.06em}
.prompt textarea{display:block;width:100%;resize:none;border:0;background:transparent;outline:none;padding:14px 6px 10px;min-height:76px;font:500 clamp(17px,1.7vw,21px)/1.45 var(--display);letter-spacing:-.01em;color:#fff}
.prompt textarea::placeholder{color:var(--ink-4)}
.prompt textarea:focus-visible{outline:none}
.prompt-in:focus-within{box-shadow:inset 0 0 0 1px rgba(121,166,255,.35);border-radius:23px}
.caret{display:inline-block;width:2px;height:1.1em;background:var(--blue-hi);vertical-align:-.15em;animation:blink 1s steps(1) infinite}
@keyframes blink{50%{opacity:0}}
.prompt-bot{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.adv{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:12px 4px 14px;border-top:1px solid var(--line);margin-top:4px}
.adv[hidden]{display:none}
.adv label,.adv fieldset{font:500 11px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3);border:0;margin:0;padding:0;min-width:0}
.adv select{display:block;width:100%;margin-top:6px;height:36px;border-radius:10px;border:1px solid var(--line-2);background:#0c0c11;padding:0 10px;font:400 13px var(--body);letter-spacing:0;text-transform:none;color:#fff}
.toggles{display:flex;gap:6px;margin-top:6px;flex-wrap:wrap}
.toggles label{display:inline-flex;align-items:center;gap:6px;height:36px;padding:0 10px;border-radius:10px;border:1px solid var(--line-2);font:400 13px var(--body);text-transform:none;letter-spacing:0;color:var(--ink-2);cursor:pointer}
.toggles input{accent-color:var(--blue)}
.stages{display:flex;gap:4px;align-items:center;flex:1;min-width:0;overflow-x:auto;scrollbar-width:none}
.stages::-webkit-scrollbar{display:none}
.stg{display:flex;align-items:center;gap:6px;height:30px;padding:0 10px;border-radius:999px;font:500 11px var(--mono);letter-spacing:.06em;color:var(--ink-4);white-space:nowrap;border:1px solid transparent;transition:color .3s,border-color .3s,background .3s}
.stg i{width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.6;transition:background .3s,box-shadow .3s}
.stg.on{color:#fff;border-color:rgba(121,166,255,.55);background:rgba(61,123,255,.12)}
.stg.on i{background:var(--blue-hi);box-shadow:0 0 10px var(--blue);opacity:1}
.stg.done{color:var(--ink-2)}
.stg.done i{background:#fff;opacity:1}
.hero-foot{display:flex;justify-content:center;gap:12px;margin:22px 0 0;padding-bottom:48px;position:relative;z-index:5}
.hero-panels-m{display:none}

/* ---------- sections ---------- */
section{position:relative}
.sec{padding:clamp(80px,12vw,150px) 0}
.sec-head{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:24px;margin-bottom:clamp(36px,5vw,64px)}
.sec-idx{font:500 11px var(--mono);letter-spacing:.24em;text-transform:uppercase;color:var(--ink-3);display:flex;align-items:center;gap:12px}
.sec-idx b{color:#fff;font-weight:500}
.sec-idx::after{content:"";width:40px;height:1px;background:var(--line-2)}
h2{font:600 clamp(30px,4.2vw,56px)/1.04 var(--display);letter-spacing:-.035em;margin:14px 0 0;max-width:16ch}
h2 em{font-style:normal;color:var(--ink-4)}
.sec-head p{margin:0;max-width:34ch;color:var(--ink-3);font-size:15px}
h3{font:600 20px/1.2 var(--display);letter-spacing:-.02em;margin:0}

.reveal{opacity:0;transform:translateY(26px);transition:opacity .9s cubic-bezier(.2,.8,.2,1),transform .9s cubic-bezier(.2,.8,.2,1);transition-delay:var(--d,0s)}
.reveal.in{opacity:1;transform:none}

/* pipeline */
.pipe{position:relative;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:12px}
.pipe-line{position:absolute;left:calc(100%/14);right:calc(100%/14);top:46px;height:1px;background:var(--line-2);overflow:hidden}
.pipe-line i{position:absolute;top:0;left:0;height:1px;width:0;background:var(--energy);box-shadow:0 0 12px var(--blue);transition:width 1.8s cubic-bezier(.4,0,.2,1)}
.pipe.in .pipe-line i{width:100%}
.pipe-line b{position:absolute;top:-2px;left:0;width:80px;height:5px;border-radius:5px;background:linear-gradient(90deg,transparent,#fff,transparent);opacity:0;animation:pulse-run 3.6s 1.8s cubic-bezier(.5,0,.5,1) infinite}
.pipe.in .pipe-line b{opacity:1}
@keyframes pulse-run{from{transform:translateX(-80px)}to{transform:translateX(calc(100vw))}}
.step{position:relative;text-align:center;padding:0 4px}
.step .node{position:relative;width:92px;height:92px;margin:0 auto 18px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle at 50% 35%,rgba(255,255,255,.08),rgba(0,0,0,.9) 70%);border:1px solid var(--line-2);transition:transform .5s cubic-bezier(.2,.8,.2,1),border-color .4s,box-shadow .4s}
.step .node::before{content:"";position:absolute;inset:-7px;border-radius:50%;border:1px dashed rgba(255,255,255,.12);animation:rot 24s linear infinite}
.step .node svg{width:34px;height:34px;color:#fff}
.step:hover .node{transform:translateY(-4px);border-color:rgba(121,166,255,.7);box-shadow:0 0 40px -8px var(--blue)}
.step .n{font:500 10px var(--mono);letter-spacing:.2em;color:var(--ink-4)}
.step h3{font-size:17px;margin:4px 0 6px}
.step p{margin:0;font-size:13px;color:var(--ink-3);line-height:1.45}
@keyframes rot{to{transform:rotate(360deg)}}

/* studios bento */
.bento{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:16px}
.card{position:relative;border-radius:22px;background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.015));border:1px solid var(--line);padding:22px;overflow:hidden;transition:border-color .4s,transform .5s cubic-bezier(.2,.8,.2,1)}
.card::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:radial-gradient(500px circle at var(--mx,50%) var(--my,0%),rgba(121,166,255,.10),transparent 45%);opacity:0;transition:opacity .4s}
.card:hover{border-color:var(--line-2)}
.card:hover::before{opacity:1}
.card-h{display:flex;align-items:center;gap:12px;margin-bottom:18px}
.card-h .glyph{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;border:1px solid var(--line-2);background:rgba(255,255,255,.03)}
.card-h .glyph svg{width:18px;height:18px}
.card-h small{display:block;font:500 10px var(--mono);letter-spacing:.2em;text-transform:uppercase;color:var(--ink-4)}
.card-h .aside{margin-left:auto;font:400 12px var(--mono);color:var(--ink-4)}
.c-tex{grid-column:span 5}.c-3d{grid-column:span 7}.c-snd{grid-column:span 6}.c-cfg{grid-column:span 6}.c-mot{grid-column:span 12}
.tool-row{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.tbtn{height:34px;min-width:34px;padding:0 10px;border-radius:10px;border:1px solid var(--line-2);background:rgba(255,255,255,.03);display:inline-flex;align-items:center;justify-content:center;gap:6px;font-size:13px;color:var(--ink-2);transition:all .2s}
.tbtn:hover{color:#fff;border-color:rgba(255,255,255,.35)}
.tbtn[aria-pressed=true]{color:#fff;border-color:var(--blue-hi);background:rgba(61,123,255,.16)}
.tbtn svg{width:15px;height:15px}
.paint{display:grid;grid-template-columns:minmax(0,1fr) 112px;gap:16px;align-items:start;margin-top:14px}
#paint{width:100%;aspect-ratio:1;image-rendering:pixelated;border-radius:12px;cursor:crosshair;touch-action:none;background:repeating-conic-gradient(#121218 0 25%,#0a0a0e 0 50%) 0 0/12.5% 12.5%;border:1px solid var(--line-2)}
.pal{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.pal button{aspect-ratio:1;border-radius:8px;border:1px solid rgba(255,255,255,.12);padding:0;transition:transform .15s}
.pal button:hover{transform:scale(1.08)}
.pal button[aria-pressed=true]{box-shadow:0 0 0 2px #000,0 0 0 4px #fff}
.mini{margin-top:14px;text-align:center}
.mini canvas{width:112px;height:112px;margin:0 auto;border-radius:12px;background:radial-gradient(circle at 50% 70%,rgba(61,123,255,.18),transparent 70%),#07070b;border:1px solid var(--line)}
.mini small{display:block;margin-top:6px;font:400 11px var(--mono);color:var(--ink-4)}

.viewer{position:relative;height:clamp(300px,34vw,420px);border-radius:16px;background:radial-gradient(ellipse at 50% 80%,rgba(61,123,255,.14),transparent 60%),radial-gradient(ellipse at 50% 20%,rgba(139,92,255,.08),transparent 60%),#050508;border:1px solid var(--line);overflow:hidden;touch-action:none}
.viewer canvas{width:100%!important;height:100%!important;cursor:grab}
.viewer canvas:active{cursor:grabbing}
.viewer .vstate{position:absolute;inset:0;display:grid;place-items:center;font:400 12px var(--mono);color:var(--ink-3);pointer-events:none}
.viewer .vstate img{max-width:80%;opacity:.8;border-radius:12px}
.viewer .vhint{position:absolute;left:14px;bottom:12px;font:400 11px var(--mono);color:var(--ink-4);pointer-events:none}
.viewer .vtri{position:absolute;right:14px;bottom:12px;font:400 11px var(--mono);color:var(--ink-4);pointer-events:none}
.seg{display:inline-flex;padding:3px;border-radius:999px;border:1px solid var(--line-2);background:rgba(255,255,255,.03);gap:2px;flex-wrap:wrap}
.seg button{height:30px;padding:0 13px;border-radius:999px;border:0;background:transparent;color:var(--ink-3);font-size:13px;transition:background .25s,color .25s}
.seg button:hover{color:#fff}
.seg button[aria-pressed=true]{background:#fff;color:#000}

.wave-wrap{position:relative;height:150px;border-radius:14px;background:#050508;border:1px solid var(--line);overflow:hidden;cursor:pointer;touch-action:none}
#wave{width:100%;height:100%}
.ph{position:absolute;top:0;bottom:0;left:0;width:1px;background:#fff;box-shadow:0 0 12px var(--blue-hi);pointer-events:none}
.snd-row{display:flex;gap:10px;align-items:center;margin-top:14px;flex-wrap:wrap}
.play{width:46px;height:46px;border-radius:50%;border:0;background:#fff;color:#000;display:grid;place-items:center;flex:none;transition:transform .2s,box-shadow .3s}
.play:hover{box-shadow:0 0 30px -4px var(--blue)}
.play svg{width:18px;height:18px}
.time{font:400 12px var(--mono);color:var(--ink-3);margin-left:auto}

.walk{position:relative;height:170px;border-radius:14px;background:#050508;border:1px solid var(--line);overflow:hidden}
#walker{width:100%;height:100%}
.sliders{display:grid;gap:12px;margin-top:16px}
.sl{display:grid;grid-template-columns:110px minmax(0,1fr) 54px;align-items:center;gap:12px;font-size:13px;color:var(--ink-2)}
.sl output{font:500 12px var(--mono);text-align:right;color:#fff}
input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:24px;background:transparent;cursor:pointer}
input[type=range]::-webkit-slider-runnable-track{height:3px;border-radius:3px;background:linear-gradient(90deg,var(--blue) 0,var(--violet) var(--p,50%),rgba(255,255,255,.12) var(--p,50%))}
input[type=range]::-moz-range-track{height:3px;border-radius:3px;background:rgba(255,255,255,.12)}
input[type=range]::-moz-range-progress{height:3px;background:var(--energy)}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:18px;height:18px;border-radius:50%;background:#fff;margin-top:-7.5px;box-shadow:0 0 0 4px rgba(61,123,255,.25)}
input[type=range]::-moz-range-thumb{width:18px;height:18px;border:0;border-radius:50%;background:#fff;box-shadow:0 0 0 4px rgba(61,123,255,.25)}
input[type=range]:focus-visible{outline:none}
input[type=range]:focus-visible::-webkit-slider-thumb{box-shadow:0 0 0 4px var(--blue-hi)}
.cfg-json{margin:14px 0 0;padding:12px 14px;border-radius:12px;background:#050508;border:1px solid var(--line);font:400 12px/1.6 var(--mono);color:var(--ink-3);overflow-x:auto}
.cfg-json b{color:var(--blue-hi);font-weight:400}

.loops{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.loop{position:relative;border-radius:14px;overflow:hidden;border:1px solid var(--line);background:#06070c;padding:0;text-align:left;color:inherit;transition:border-color .3s,transform .4s cubic-bezier(.2,.8,.2,1)}
.loop:hover{border-color:var(--line-2);transform:translateY(-3px)}
.loop .spr{aspect-ratio:var(--ar,4/3);background-repeat:no-repeat;background-size:calc(var(--n)*100%) 100%;background-position:0 0}
.loop.fx .spr{aspect-ratio:1;background-color:#000;mix-blend-mode:screen;image-rendering:auto}
.loop .lab{display:flex;align-items:center;gap:8px;padding:10px 12px;border-top:1px solid var(--line);font:500 11px var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3)}
.loop .lab .pp{margin-left:auto;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;border:1px solid var(--line-2)}
.loop .lab .pp svg{width:9px;height:9px}
.loops.fxrow{grid-template-columns:repeat(4,minmax(0,1fr));margin-top:12px}

/* mods in game */
.mods{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.mod{border-radius:22px;border:1px solid var(--line);overflow:hidden;background:#050508;transition:transform .6s cubic-bezier(.2,.8,.2,1),border-color .4s;transform-style:preserve-3d}
.mod:hover{border-color:var(--line-2)}
.scene{position:relative;aspect-ratio:4/3.3;overflow:hidden}
.scene canvas.world{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated}
.scene .item{position:absolute;inset:6% 8% 10%;width:84%;height:84%;object-fit:contain;mask-image:radial-gradient(closest-side,#000 62%,transparent 100%);-webkit-mask-image:radial-gradient(closest-side,#000 62%,transparent 100%);transition:opacity .5s,transform .7s cubic-bezier(.2,.8,.2,1);filter:drop-shadow(0 18px 24px rgba(0,0,0,.6))}
.scene .item.off{opacity:0;transform:scale(.94) translateY(8px)}
.scene canvas.drop{position:absolute;left:50%;top:50%;width:46%;height:46%;transform:translate(-50%,-56%);image-rendering:pixelated}
.hud{position:absolute;left:50%;bottom:10px;transform:translateX(-50%);display:flex;gap:2px;padding:3px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.18)}
.hud i{width:22px;height:22px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.04)}
.hud i.sel{border-color:#fff;box-shadow:inset 0 0 0 1px #fff}
.mod-f{display:flex;align-items:center;gap:12px;padding:16px 18px;border-top:1px solid var(--line);flex-wrap:wrap}
.mod-f h3{font-size:16px}
.mod-f small{display:block;font:400 11px var(--mono);color:var(--ink-4);margin-top:2px}
.mod-f .seg{margin-left:auto}

/* games */
.games{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:16px;align-items:stretch}
.mc{position:relative;border-radius:22px;padding:28px;border:1px solid rgba(121,166,255,.35);background:radial-gradient(ellipse at 30% 0%,rgba(61,123,255,.18),transparent 60%),radial-gradient(ellipse at 100% 100%,rgba(139,92,255,.16),transparent 60%),#06060a;overflow:hidden;display:flex;flex-direction:column;min-height:360px}
.mc img{width:84px;height:auto;filter:drop-shadow(0 20px 30px rgba(61,123,255,.35))}
.mc h3{font-size:clamp(28px,3vw,40px);letter-spacing:-.03em;margin-top:auto}
.live{display:inline-flex;align-items:center;gap:8px;font:500 11px var(--mono);letter-spacing:.2em;text-transform:uppercase;color:#fff;margin-top:14px}
.live::before{content:"";width:8px;height:8px;border-radius:50%;background:#fff;box-shadow:0 0 0 0 rgba(255,255,255,.6);animation:ping 2s infinite}
@keyframes ping{0%{box-shadow:0 0 0 0 rgba(121,166,255,.7)}100%{box-shadow:0 0 0 12px rgba(121,166,255,0)}}
.mc .btn{align-self:flex-start;margin-top:22px}
.soon{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.g{position:relative;border-radius:18px;border:1px solid var(--line);background:#07070b;aspect-ratio:1/1.05;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:14px;overflow:hidden;text-align:center}
.g .gi{width:56%;aspect-ratio:1;display:grid;place-items:center}
.g .gi img{max-width:100%;max-height:100%;object-fit:contain;filter:grayscale(1) brightness(.85) contrast(1.05);opacity:.75;transition:filter .5s,opacity .5s,transform .6s cubic-bezier(.2,.8,.2,1)}
.g:hover .gi img{filter:none;opacity:1;transform:scale(1.06)}
.g .mono-ph{width:100%;aspect-ratio:1;border-radius:18px;border:1px solid var(--line-2);display:grid;place-items:center;font:600 clamp(18px,2vw,26px) var(--display);letter-spacing:-.02em;color:var(--ink-3);background:repeating-linear-gradient(135deg,rgba(255,255,255,.025) 0 6px,transparent 6px 12px)}
.g:hover .mono-ph{color:#fff;border-color:rgba(255,255,255,.3)}
.g b{font:600 14px var(--display)}
.g small{position:absolute;top:10px;right:10px;font:500 9px var(--mono);letter-spacing:.16em;text-transform:uppercase;color:var(--ink-4);border:1px solid var(--line-2);border-radius:999px;padding:2px 7px}

/* plans */
.plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.plan{position:relative;border-radius:24px;padding:28px 26px 26px;border:1px solid var(--line);background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.01));display:flex;flex-direction:column;overflow:hidden;transition:transform .6s cubic-bezier(.2,.8,.2,1),border-color .4s}
.plan:hover{transform:translateY(-6px);border-color:var(--line-2)}
.plan::after{content:"";position:absolute;left:-20%;right:-20%;top:-60%;height:80%;background:radial-gradient(closest-side,var(--tint),transparent);opacity:.18;pointer-events:none;transition:opacity .5s}
.plan:hover::after{opacity:.32}
.plan.katara{--tint:#3d7bff}.plan.saka{--tint:#6a6cff}.plan.yakko{--tint:#8b5cff}
.plan .sig{width:96px;height:96px;margin-bottom:22px}
.plan .tier{font:500 10px var(--mono);letter-spacing:.22em;text-transform:uppercase;color:var(--ink-4)}
.plan h3{font-size:32px;letter-spacing:-.03em;margin:6px 0 4px}
.plan .lead{margin:0 0 20px;color:var(--ink-2);font-size:15px}
.plan ul{list-style:none;margin:0 0 26px;padding:0;display:grid;gap:10px;font-size:14px;color:var(--ink-2)}
.plan li{display:flex;gap:10px;align-items:flex-start}
.plan li svg{flex:none;width:16px;height:16px;margin-top:2px;color:var(--blue-hi)}
.plan li.dim{color:var(--ink-4)}
.plan li.dim svg{color:var(--ink-4)}
.plan .btn{margin-top:auto}
.plan.yakko{border-color:rgba(139,92,255,.35)}
.free{margin-top:16px;border-radius:18px;border:1px dashed var(--line-2);padding:16px 22px;display:flex;align-items:center;gap:16px;flex-wrap:wrap;color:var(--ink-2);font-size:15px}
.free b{font:600 16px var(--display);color:#fff}
.free .btn{margin-left:auto}

/* plan icons */
.sig .w1{animation:wave 5s linear infinite}.sig .w2{animation:wave 3.4s linear infinite reverse}.sig .w3{animation:wave 7s linear infinite}
@keyframes wave{to{transform:translateX(-48px)}}
.sig .bob{animation:bob 4s ease-in-out infinite;transform-origin:48px 48px}
@keyframes bob{50%{transform:translateY(-2px)}}
.sig .fl1{transform-origin:48px 78px;animation:flick 2.2s ease-in-out infinite}
.sig .fl2{transform-origin:48px 78px;animation:flick 1.7s ease-in-out infinite reverse}
.sig .fl3{transform-origin:48px 78px;animation:flick 1.3s ease-in-out infinite}
@keyframes flick{0%,100%{transform:scale(1,1) skewX(0)}30%{transform:scale(.97,1.05) skewX(-3deg)}65%{transform:scale(1.03,.96) skewX(3deg)}}
.sig .em{animation:rise 2.6s ease-in infinite;opacity:0}
.sig .em:nth-of-type(2){animation-delay:.9s}.sig .em:nth-of-type(3){animation-delay:1.7s}
@keyframes rise{0%{transform:translateY(0);opacity:0}20%{opacity:1}100%{transform:translateY(-34px);opacity:0}}
.sig .r1{transform-origin:48px 48px;animation:rot 18s linear infinite}
.sig .r2{transform-origin:48px 48px;animation:rot 12s linear infinite reverse}
.sig .spark{transform-origin:48px 48px;animation:spark 2.8s ease-in-out infinite}
@keyframes spark{0%,100%{transform:scale(.86) rotate(0);opacity:.85}50%{transform:scale(1.08) rotate(45deg);opacity:1}}

/* bridge */
.bridge{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);gap:clamp(24px,4vw,64px);align-items:center}
.bridge-copy .btn-nx{margin-top:26px;--h:52px;padding:0 22px 0 14px;background:#0b0b10;border-color:rgba(255,255,255,.22)}
.bridge-copy .btn-nx img{height:20px;width:auto}
.bridge-copy .btn-nx:hover{border-color:rgba(121,166,255,.7);box-shadow:0 0 40px -10px var(--blue)}
.feats{list-style:none;margin:28px 0 0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:18px 22px}
.feats li{display:flex;gap:12px;align-items:flex-start;font-size:14px;color:var(--ink-3)}
.feats li b{display:block;color:#fff;font:600 15px var(--display);margin-bottom:2px}
.feats svg{flex:none;width:20px;height:20px;margin-top:2px;color:var(--blue-hi)}
.key{margin-top:28px;display:flex;gap:8px;align-items:stretch;flex-wrap:wrap}
.key label{width:100%;font:500 11px var(--mono);letter-spacing:.14em;text-transform:uppercase;color:var(--ink-3)}
.key input{flex:1;min-width:0;height:46px;border-radius:12px;border:1px solid var(--line-2);background:#07070b;padding:0 14px;font:400 14px var(--mono);color:#fff}
.key input::placeholder{color:var(--ink-4)}
.key input:focus-visible{outline:2px solid var(--blue-hi);outline-offset:1px}
.link-viz{position:relative;border-radius:26px;border:1px solid var(--line);background:radial-gradient(ellipse at 50% 30%,rgba(61,123,255,.10),transparent 60%),#040406;padding:clamp(18px,3vw,34px);overflow:hidden}
.link-viz svg.lnk{width:100%;height:auto;overflow:visible}
.srv-card{margin:0 auto;max-width:440px;border-radius:18px;border:1px solid var(--line-2);background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.015));padding:16px;backdrop-filter:blur(10px)}
.srv-card .top{display:flex;align-items:center;gap:12px}
.srv-card .top .ic{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:#0d0d12;border:1px solid var(--line-2)}
.srv-card .top .ic img{width:24px}
.srv-card .top b{font:600 15px var(--display);display:block}
.srv-card .top small{font:400 12px var(--mono);color:var(--ink-3)}
.srv-card .top .on{margin-left:auto;display:flex;align-items:center;gap:6px;font:500 11px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--ink-2)}
.srv-card .top .on::before{content:"";width:7px;height:7px;border-radius:50%;background:#fff;box-shadow:0 0 10px #fff}
.modlist{list-style:none;margin:14px 0 0;padding:0;display:grid;gap:6px}
.modlist li{display:flex;align-items:center;gap:10px;height:40px;padding:0 12px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid var(--line);font:400 13px var(--mono);color:var(--ink-2)}
.modlist li span{margin-left:auto;font-size:11px;color:var(--ink-4);letter-spacing:.08em;text-transform:uppercase}
.modlist li.new{border-color:rgba(121,166,255,.6);color:#fff;background:rgba(61,123,255,.1);animation:slidein 6s cubic-bezier(.2,.8,.2,1) infinite}
.modlist li.new span{color:var(--blue-hi)}
@keyframes slidein{0%,30%{opacity:0;transform:translateY(-14px) scale(.97)}42%,92%{opacity:1;transform:none}100%{opacity:0}}
.lnk .travel{offset-path:path("M120 60 C 230 60, 330 60, 440 60");animation:travel 6s cubic-bezier(.6,0,.3,1) infinite}
@keyframes travel{0%{offset-distance:0%;opacity:0}6%{opacity:1}30%{offset-distance:100%;opacity:1}34%,100%{offset-distance:100%;opacity:0}}
.lnk .dash{stroke-dasharray:2 8;animation:flow 1.4s linear infinite}

/* final cta */
.final{text-align:center;padding:clamp(100px,14vw,180px) 0 clamp(80px,10vw,140px);overflow:hidden}
.final .halo{position:absolute;left:50%;top:50%;width:min(760px,130vw);aspect-ratio:1;transform:translate(-50%,-50%);pointer-events:none;z-index:-1}
.final .halo i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(255,255,255,.07)}
.final .halo i:nth-child(2){inset:12%;border-color:rgba(121,166,255,.14);border-style:dashed;animation:rot 60s linear infinite}
.final .halo i:nth-child(3){inset:26%;border-color:rgba(139,92,255,.18)}
.final .halo i:nth-child(4){inset:38%;border:0;background:radial-gradient(circle at 45% 40%,#fff 0,#a9c3ff 8%,var(--blue) 26%,var(--violet) 48%,transparent 70%);filter:blur(6px);opacity:.55;animation:breathe 6s ease-in-out infinite}
@keyframes breathe{50%{transform:scale(1.06);opacity:.7}}
.final h2{margin:18px auto 0;max-width:14ch;font-size:clamp(38px,6vw,84px)}
.final .ctas{display:flex;gap:12px;justify-content:center;margin-top:36px;flex-wrap:wrap}

/* footer */
footer{border-top:1px solid var(--line);padding:40px 0 48px}
footer .wrap{display:flex;align-items:center;gap:24px;flex-wrap:wrap}
footer .brand img{height:20px}
.byline{display:flex;align-items:center;gap:12px;font:500 11px var(--mono);letter-spacing:.2em;text-transform:uppercase;color:var(--ink-3);text-decoration:none}
.byline img{height:22px;width:auto}
footer nav{margin-left:auto;display:flex;gap:18px;flex-wrap:wrap}
footer nav a{color:var(--ink-3);text-decoration:none;font-size:14px}
footer nav a:hover{color:#fff}
footer .copy{width:100%;font:400 12px var(--mono);color:var(--ink-4)}

.toast{position:fixed;left:50%;bottom:24px;z-index:90;transform:translate(-50%,30px);opacity:0;pointer-events:none;padding:12px 18px;border-radius:14px;background:rgba(16,16,22,.95);border:1px solid var(--line-2);font-size:14px;color:#fff;box-shadow:0 20px 50px -10px #000;transition:all .4s cubic-bezier(.2,.8,.2,1);max-width:calc(100vw - 32px);text-align:center}
.toast.show{opacity:1;transform:translate(-50%,0)}

/* ---------- responsive ---------- */
@media (max-width:1180px){
  .panel{--pw:212px}
  .p-code,.p-3d{top:2%}
  .c-tex,.c-3d,.c-snd,.c-cfg{grid-column:span 12}
  .c-tex .paint{grid-template-columns:minmax(0,360px) 140px;justify-content:start}
  .loops{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:980px){
  .nav-links{display:none}
  .nav-cta .btn:not(.btn-solid){display:none}
  .menu-btn{display:grid;margin-left:auto}
  .nav-links.open{display:flex;position:absolute;top:68px;left:0;right:0;flex-direction:column;padding:12px var(--gut) 20px;background:rgba(0,0,0,.94);border-bottom:1px solid var(--line);backdrop-filter:blur(16px)}
  .nav-links.open a{font-size:17px;padding:12px 0;color:#fff;border-radius:0}
  .stage{height:min(78vw,400px)}
  .core{--core:min(84vw,400px)}
  .stage .panel,#streams{display:none}
  .hero-panels-m{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;padding:4px var(--gut) 8px;margin:18px 0 0;scrollbar-width:none;position:relative;z-index:5}
  .hero-panels-m::-webkit-scrollbar{display:none}
  .hero-panels-m .panel{position:relative;inset:auto;flex:0 0 232px;scroll-snap-align:center;--pw:232px}
  .pipe{grid-template-columns:minmax(0,1fr);gap:0}
  .pipe-line{left:45px;right:auto;top:20px;bottom:20px;width:1px;height:auto}
  .pipe-line i{width:1px!important;height:0;transition:height 1.8s cubic-bezier(.4,0,.2,1)}
  .pipe.in .pipe-line i{height:100%}
  .pipe-line b{display:none}
  .step{display:grid;grid-template-columns:92px minmax(0,1fr);gap:18px;text-align:left;align-items:center;padding:10px 0}
  .step .node{margin:0}
  .games,.bridge{grid-template-columns:minmax(0,1fr)}
  .plans{grid-template-columns:minmax(0,1fr);max-width:560px;margin:0 auto}
  .mods{grid-template-columns:minmax(0,1fr);max-width:560px;margin:0 auto}
  .sec-head{grid-template-columns:minmax(0,1fr)}
  .adv{grid-template-columns:minmax(0,1fr)}
}
@media (max-width:640px){
  body{font-size:15px}
  .hero-copy{margin-top:0}
  .prompt{margin-left:12px;margin-right:12px;border-radius:20px}
  .prompt-in{border-radius:19px;padding:12px}
  .prompt-hint{display:none}
  .prompt-bot{flex-direction:column;align-items:stretch}
  .prompt-bot .btn-create{width:100%}
  .stages{order:2}
  .hero-foot{flex-direction:column;align-items:stretch;padding:0 var(--gut) 40px}
  .soon{grid-template-columns:repeat(2,minmax(0,1fr))}
  .loops,.loops.fxrow{grid-template-columns:repeat(2,minmax(0,1fr))}
  .c-tex .paint{grid-template-columns:minmax(0,1fr)}
  .c-tex .side{display:grid;grid-template-columns:minmax(0,1fr) 112px;gap:14px;align-items:start}
  .c-tex .mini{margin-top:0}
  .pal{grid-template-columns:repeat(6,1fr)}
  .card{padding:16px;border-radius:18px}
  .card-h .aside{display:none}
  .feats{grid-template-columns:minmax(0,1fr)}
  .sl{grid-template-columns:92px minmax(0,1fr) 46px;gap:8px}
  .mod-f .seg{margin-left:0}
  .free .btn{margin-left:0}
  footer nav{margin-left:0}
  .step{grid-template-columns:72px minmax(0,1fr)}
  .step .node{width:72px;height:72px}
  .step .node svg{width:28px;height:28px}
  .pipe-line{left:35px}
}

@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important;scroll-behavior:auto!important}
  .reveal{opacity:1;transform:none}
  .modlist li.new{animation:none;opacity:1}
  .lnk .travel{animation:none;offset-distance:100%;opacity:1}
  .sig *{animation:none!important}
  .em{opacity:.8!important}
}

