// Cyrus Core: WebGL energy sphere + SVG orbital rings + energy streams to the studio panels + particle field.
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const $ = (s) => document.querySelector(s);
const hero = $('.hero'), stage = $('#stage'), coreEl = $('#core'), canvas = $('#coreGL');
const SVGNS = 'http://www.w3.org/2000/svg';
let heroVisible = true, pageVisible = !document.hidden;
const mouse = { x: 0, y: 0, tx: 0, ty: 0 };
let pulse = 0, hueShift = 0, hueTarget = 0, activeStage = null;

/* ---------------- WebGL sphere ---------------- */
const gl = canvas.getContext('webgl', { premultipliedAlpha: true, alpha: true, antialias: false, powerPreference: 'low-power' });
let prog, uRes, uT, uM, uP, uH;
const VS = 'attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';
const FS = `precision highp float;
uniform vec2 uRes;uniform float uT;uniform vec2 uM;uniform float uP;uniform float uH;
float h(vec3 p){p=fract(p*.3183099+.1);p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
float n(vec3 x){vec3 i=floor(x),f=fract(x);f=f*f*(3.-2.*f);
return mix(mix(mix(h(i),h(i+vec3(1,0,0)),f.x),mix(h(i+vec3(0,1,0)),h(i+vec3(1,1,0)),f.x),f.y),
mix(mix(h(i+vec3(0,0,1)),h(i+vec3(1,0,1)),f.x),mix(h(i+vec3(0,1,1)),h(i+vec3(1,1,1)),f.x),f.y),f.z);}
float fbm(vec3 p){float a=.5,s=0.;for(int i=0;i<4;i++){s+=a*n(p);p=p*2.03+vec3(1.7,9.2,3.1);a*=.5;}return s;}
mat3 ry(float a){float c=cos(a),s=sin(a);return mat3(c,0,-s,0,1,0,s,0,c);}
mat3 rx(float a){float c=cos(a),s=sin(a);return mat3(1,0,0,0,c,s,0,-s,c);}
void main(){
 vec2 uv=(gl_FragCoord.xy-.5*uRes)/uRes.y;
 float R=.25+.014*uP;
 float d=length(uv);
 vec3 blue=vec3(.24,.48,1.),vio=vec3(.56,.36,1.),wh=vec3(1.);
 float ang=atan(uv.y,uv.x);
 vec3 rim=mix(blue,vio,.5+.5*sin(ang+uT*.4+uH));
 vec3 col=vec3(0.);
 if(d<R){
  float z=sqrt(R*R-d*d);
  vec3 nr=vec3(uv,z)/R;
  vec3 p=ry(uT*.16+uM.x*.4)*rx(.35-uM.y*.3)*nr;
  float q=fbm(p*2.4+vec3(0.,uT*.14,0.));
  float r=fbm(p*3.3+q*2.3-vec3(uT*.11));
  float fil=pow(1.-abs(r*2.-1.),7.);
  float fil2=pow(1.-abs(q*2.-1.),14.);
  vec3 L=normalize(vec3(uM*1.1+vec2(-.35,.45),1.));
  float lam=max(dot(nr,L),0.);
  float fres=pow(1.-nr.z,2.3);
  vec3 base=mix(vec3(.01,.015,.05),mix(blue,vio,q*1.2),.5*lam+.1);
  col=base+wh*fil*(.45+.7*lam)*(1.+uP)+mix(blue,wh,.35)*fil2*.55+rim*fres*1.5+wh*pow(lam,28.)*.3;
  col*=smoothstep(R,R-.003,d);
 }
 float g=max(d-R,0.);
 col+=rim*(exp(-g*26.)*.7+exp(-g*7.)*.2)*(1.+uP*.7)*step(R-.003,d);
 col=min(col,vec3(1.));
 float a=max(col.r,max(col.g,col.b));
 gl_FragColor=vec4(col,a);
}`;
function initGL() {
  if (!gl) return false;
  const sh = (t, s) => { const o = gl.createShader(t); gl.shaderSource(o, s); gl.compileShader(o); if (!gl.getShaderParameter(o, gl.COMPILE_STATUS)) { console.warn(gl.getShaderInfoLog(o)); return null; } return o; };
  const v = sh(gl.VERTEX_SHADER, VS), f = sh(gl.FRAGMENT_SHADER, FS);
  if (!v || !f) return false;
  prog = gl.createProgram(); gl.attachShader(prog, v); gl.attachShader(prog, f); gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return false;
  gl.useProgram(prog);
  const b = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, b);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(prog, 'p'); gl.enableVertexAttribArray(loc); gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
  uRes = gl.getUniformLocation(prog, 'uRes'); uT = gl.getUniformLocation(prog, 'uT'); uM = gl.getUniformLocation(prog, 'uM');
  uP = gl.getUniformLocation(prog, 'uP'); uH = gl.getUniformLocation(prog, 'uH');
  gl.clearColor(0, 0, 0, 0);
  return true;
}
const glOK = initGL();
if (!glOK) {
  // CSS fallback orb
  canvas.style.background = 'radial-gradient(circle at 42% 38%,#fff 0,#a9c3ff 9%,#3d7bff 26%,#8b5cff 44%,rgba(139,92,255,.15) 50%,transparent 62%)';
}
function sizeGL() {
  const r = coreEl.getBoundingClientRect(), dpr = Math.min(devicePixelRatio || 1, 1.5);
  canvas.width = Math.max(2, Math.round(r.width * dpr)); canvas.height = Math.max(2, Math.round(r.height * dpr));
  if (glOK) gl.viewport(0, 0, canvas.width, canvas.height);
}
function drawGL(t) {
  if (!glOK) return;
  gl.uniform2f(uRes, canvas.width, canvas.height); gl.uniform1f(uT, t); gl.uniform2f(uM, mouse.x, mouse.y);
  gl.uniform1f(uP, pulse); gl.uniform1f(uH, hueShift);
  gl.clear(gl.COLOR_BUFFER_BIT); gl.drawArrays(gl.TRIANGLES, 0, 3);
}

/* ---------------- orbital rings ---------------- */
const RINGS = [
  { rx: 262, ry: 62, rot: -14, sp: 0.34, col: '#79a6ff', w: 1.2, dash: '' },
  { rx: 318, ry: 104, rot: 24, sp: -0.21, col: '#b49bff', w: 1, dash: '2 7' },
  { rx: 214, ry: 34, rot: 76, sp: 0.46, col: '#ffffff', w: .8, dash: '' },
];
const back = $('#ringsBack'), front = $('#ringsFront');
RINGS.forEach((r, i) => {
  r.t = i * 2.1;
  for (const [svg, sweep, op] of [[back, 0, .22], [front, 1, .6]]) {
    const g = document.createElementNS(SVGNS, 'g'); g.setAttribute('transform', `rotate(${r.rot})`);
    const p = document.createElementNS(SVGNS, 'path');
    p.setAttribute('d', `M${r.rx} 0 A${r.rx} ${r.ry} 0 0 ${sweep} ${-r.rx} 0`);
    p.setAttribute('stroke', r.col); p.setAttribute('stroke-width', r.w); p.setAttribute('opacity', op);
    if (r.dash) p.setAttribute('stroke-dasharray', r.dash);
    const dot = document.createElementNS(SVGNS, 'circle'); dot.setAttribute('r', i === 2 ? 2.5 : 3.5); dot.setAttribute('fill', '#fff');
    dot.style.filter = `drop-shadow(0 0 6px ${r.col})`;
    g.append(p, dot); svg.append(g);
    (svg === back ? (r.dBack = dot) : (r.dFront = dot));
  }
});
function drawRings(dt) {
  for (const r of RINGS) {
    r.t += dt * r.sp * (1 + pulse * 1.5);
    const x = r.rx * Math.cos(r.t), y = r.ry * Math.sin(r.t), fr = Math.sin(r.t) > 0;
    for (const d of [r.dBack, r.dFront]) { d.setAttribute('cx', x.toFixed(1)); d.setAttribute('cy', y.toFixed(1)); }
    r.dFront.style.opacity = fr ? 1 : 0; r.dBack.style.opacity = fr ? 0 : .5;
  }
}

/* ---------------- streams core -> panels ---------------- */
const streamsSvg = $('#streams');
let streams = [];
function layoutStreams() {
  streams.forEach((s) => s.g.remove()); streams = [];
  if (getComputedStyle(streamsSvg).display === 'none') return;
  const sr = stage.getBoundingClientRect(), cr = coreEl.getBoundingClientRect();
  const cx = cr.left + cr.width / 2 - sr.left, cy = cr.top + cr.height / 2 - sr.top, R = cr.height * 0.25 * 1.02;
  streamsSvg.setAttribute('viewBox', `0 0 ${sr.width} ${sr.height}`);
  stage.querySelectorAll('.panel').forEach((pn) => {
    const pr = pn.getBoundingClientRect();
    const left = pr.left + pr.width / 2 < sr.left + cx;
    const ax = (left ? pr.right : pr.left) - sr.left, ay = pr.top + pr.height / 2 - sr.top;
    const ang = Math.atan2(ay - cy, ax - cx);
    const sx = cx + Math.cos(ang) * R, sy = cy + Math.sin(ang) * R;
    const dx = (ax - sx) * 0.55;
    const d = `M${sx.toFixed(1)} ${sy.toFixed(1)} C${(sx + dx).toFixed(1)} ${sy.toFixed(1)} ${(ax - dx).toFixed(1)} ${ay.toFixed(1)} ${ax.toFixed(1)} ${ay.toFixed(1)}`;
    const g = document.createElementNS(SVGNS, 'g');
    const base = document.createElementNS(SVGNS, 'path'); base.setAttribute('d', d); base.setAttribute('class', 'base');
    const flow = document.createElementNS(SVGNS, 'path'); flow.setAttribute('d', d); flow.setAttribute('class', 'flow'); flow.setAttribute('stroke', 'url(#sg)');
    const pk = document.createElementNS(SVGNS, 'circle'); pk.setAttribute('r', 3); pk.setAttribute('fill', '#fff'); pk.setAttribute('class', 'packet');
    pk.style.filter = 'drop-shadow(0 0 6px #79a6ff)';
    g.append(base, flow, pk); streamsSvg.append(g);
    streams.push({ g, flow, pk, len: flow.getTotalLength(), key: pn.dataset.stage, t: Math.random() });
  });
  setActive(activeStage);
}
function setActive(key) {
  activeStage = key;
  streams.forEach((s) => { const on = s.key === key; s.flow.classList.toggle('on', on); s.pk.classList.toggle('on', on && !reduce); });
}
function drawPackets(dt) {
  for (const s of streams) {
    if (s.key !== activeStage) continue;
    s.t = (s.t + dt * 0.9) % 1;
    const p = s.flow.getPointAtLength(s.t * s.len);
    s.pk.setAttribute('cx', p.x.toFixed(1)); s.pk.setAttribute('cy', p.y.toFixed(1));
  }
}

/* ---------------- particles ---------------- */
const pc = $('#particles'), px = pc.getContext('2d');
let parts = [], pw = 0, ph = 0;
function sizeParticles() {
  const r = hero.getBoundingClientRect(), dpr = Math.min(devicePixelRatio || 1, 2);
  pw = r.width; ph = r.height; pc.width = pw * dpr; pc.height = ph * dpr; px.setTransform(dpr, 0, 0, dpr, 0, 0);
  const n = pw < 700 ? 46 : 110;
  parts = Array.from({ length: n }, () => ({ a: Math.random() * Math.PI * 2, r: 120 + Math.random() * Math.max(pw, ph) * .6, z: Math.random(), s: (Math.random() * .5 + .2) * (Math.random() < .5 ? -1 : 1), tw: Math.random() * 6 }));
}
function drawParticles(t, dt) {
  px.clearRect(0, 0, pw, ph);
  const cr = coreEl.getBoundingClientRect(), hr = hero.getBoundingClientRect();
  const cx = cr.left + cr.width / 2 - hr.left, cy = cr.top + cr.height / 2 - hr.top;
  for (const p of parts) {
    p.a += dt * p.s * 0.03 * (0.4 + p.z) * (1 + pulse * 2);
    const x = cx + Math.cos(p.a) * p.r - mouse.x * 30 * p.z, y = cy + Math.sin(p.a) * p.r * 0.55 + mouse.y * 20 * p.z;
